const repoRaw=x=>'https://raw.githubusercontent.com/'+x.repo+'/'+x.sha+'/'+repoEncoded(x.path);
const repoGit=x=>'https://github.com/'+x.repo+'/blob/'+x.sha+'/'+repoEncoded(x.path);
s.ms.repo=s.ms.repo&&typeof s.ms.repo==='object'?s.ms.repo:{};
s.ms.repo.notes=s.ms.repo.notes||{};s.ms.repo.read=s.ms.repo.read||{};
const repoStats=()=>({documents:repoSourceRows.length,labGuides:repoTraining.labs.length,additionalGuides:repoTraining.guides.length,retrievedLearn:repoTraining.learn.filter(x=>!x[4]).length+moreLearnFiles.length,readMarked:Object.keys(s.ms.repo.read).filter(k=>s.ms.repo.read[k]).length,notes:Object.values(s.ms.repo.notes).filter(n=>String(n||'').trim()).length});
function repoSourceButton(x,label='Open versioned source'){return '<button class="btn" data-route="course/source/'+H(x.id)+'">'+H(label)+'</button>';}
function repoNoteForm(id,label){return '<form class="un-repo-note" data-id="'+H(id)+'"><label><b>'+H(label)+'</b><textarea name="note" aria-label="'+H(label)+'">'+H(s.ms.repo.notes[id]||'')+'</textarea></label><button type="submit" class="btn">Save local evidence</button></form>';}
function repoSteps(text){const parts=String(text).split(/(?:^|\s)(?:[1-9]|1[0-9])\.\s+/).filter(Boolean);return parts.length>1?'<ol>'+parts.map(P).map(p=>'<li>'+p+'</li>').join('')+'</ol>':P(text);}
function repoLabCard(n){const a=repoTraining.labs[n],f=repoSourceMap.get('sc-'+n);return '<details class="un-detail un-repo-lab" id="repo-lab-'+n+'"><summary>SC-300 Lab '+String(n).padStart(2,'0')+' · '+H(a[1])+'</summary><div class="un-detail-body">'+P('Read the updated source qualification before the archived guided procedure.')+phase1LabForNumber(n)+'<div class="un-kicker">Original academy adaptation of the retrieved official lab</div><h3>Understand the mechanism</h3>'+P(a[2])+'<h3>Guided procedure · no live changes</h3>'+repoSteps(a[3])+'<h3>Verification and troubleshooting</h3>'+P(a[4])+'<h3>Predict the result before revealing the explanation</h3>'+P(a[5])+detail('Reveal reasoning',P(a[6]))+repoNoteForm('lab-'+n,'Record your own prediction, configuration and verification evidence')+'<h3>What the upstream document covers</h3>'+P(f.numbered+' numbered instruction lines in the retrieved document (not a count of distinct skills). Some source steps may be historical, require instructor accounts, or incur charges.')+'<ul>'+f.tasks.map(t=>'<li>'+H(t)+'</li>').join('')+'</ul>'+labTaskCard(n)+B('course/lab-steps/'+n,'Open numbered instruction workbook')+repoSourceButton(f,'Read exact original lab text')+'<p>'+A(repoGit(f),'Open pinned GitHub document')+'</p>'+(n===0?'':B(msLabs[n][2],'Related existing practice model'))+P('No paid trials, licensed service activation or real tenant changes are performed. The original instructions are archival reference; follow current Microsoft documentation only in an approved lab.')+'</div></details>';}
function repoGuideCard(n){const a=repoTraining.guides[n],patterns=a[3].split('|');const files=repoSourceRows.filter(x=>x.repo===a[2]&&patterns.some(p=>x.path.includes(p)));
return '<details class="un-detail un-repo-guide" id="repo-guide-'+n+'"><summary>'+H(a[1])+'</summary><div class="un-detail-body"><div class="un-kicker">Supplementary Microsoft repository instruction</div><h3>What it is and how it works</h3>'+P(a[4])+'<h3>Worked practice and system relationships</h3>'+P(a[5])+'<h3>Verify and qualify the procedure</h3>'+P(a[6])+repoNoteForm('guide-'+n,'Write your explanation and test evidence')+'<h4>Retrieved source files ('+files.length+')</h4>'+files.map(x=>'<div class="un-word">'+H(x.module?x.path.split('/').at(-1):x.title)+' '+repoSourceButton(x,'Read source')+'</div>').join('')+'<p>'+A('https://github.com/'+a[2],'Microsoft source repository')+'</p></div></details>';}
function repoUnit(c,i){const guides=repoTraining.guides.map((x,n)=>[x,n]).filter(([x,n])=>x[0]===c[0]&&repoGuideUnit[n]===i);const labs=repoTraining.labs.map((x,n)=>[x,n]).filter(([x,n])=>x[0]===c[0]&&repoLabUnit[n]===i);if(!guides.length&&!labs.length)return '';return '<section class="un-depth"><h3>Repository-based teaching and lab walkthroughs</h3>'+P('Study the relevant mechanisms and complete the paper or simulated tasks before moving on. The source files are optional reference reading, not separate courses.')+guides.map(([,n])=>repoGuideCard(n)).join('')+labs.map(([,n])=>repoLabCard(n)).join('')+'</section>';}
function repoSourceChapter(c){const files=repoSourceRows.filter(x=>x.chapter===c[0]);if(!files.length)return '';const names=[...new Set(files.map(x=>x.repo))];return detail('Retrieved Microsoft source documents · '+files.length+' files',P('Exact pinned source files, grouped by repository. Retrieved means the document was fetched successfully during the audit; it does not establish that every instruction was validated or taught. Open source text on demand; the browser makes only a read-only request.')+names.map(name=>detail(name,files.filter(x=>x.repo===name).map(x=>'<div class="un-word"><b>'+H(x.title.slice(0,180))+'</b><p class="small muted">'+H(x.path)+'</p>'+repoSourceButton(x,s.ms.repo.read[x.id]?'Review marked source':'Open original source')+'</div>').join(''))).join(''));}
