function splitPipe(str){let quote='',parts=[],part='';for(const ch of str){if(quote){part+=ch;if(ch===quote)quote='';}else if(ch==="'"||ch==='"'){quote=ch;part+=ch;}else if(ch==='|'){parts.push(part.trim());part='';}else part+=ch;}if(quote)throw Error('Unclosed quoted literal');parts.push(part.trim());if(parts.some(x=>!x))throw Error('Empty pipeline stage');return parts;}
function queryEval(mode,input){try{
 if(!['ps','kql'].includes(mode)||typeof input!=='string'||input.length>1200)throw Error('Choose PowerShell or KQL and enter a short supported query.');
 const parts=splitPipe(input.trim()),root=parts.shift().replace(/\s+/g,' ').toLowerCase();
 let key=root;if(mode==='ps'){if(root==='get-mguser -all'||root==='get-mguser')key='get-mguser';else if(root==='get-aduser -filter *')key='get-aduser';else if(root==='get-ciminstance -classname win32_networkadapterconfiguration')key='get-ciminstance win32_networkadapterconfiguration';else if(root!=='get-netipconfiguration'&&root!=='get-ciminstance win32_networkadapterconfiguration')throw Error('Unsupported read-only cmdlet or parameters.');}else if(!['signinlogs','auditlogs'].includes(key))throw Error('Unsupported KQL fixture table.');
 if(!queryData[key])throw Error('Unknown source.');
 let rows=queryData[key].map(x=>({...x})),schema=Object.keys(rows[0]),trace=[{stage:root,rows:rows.length,fields:schema.slice()}];
 const field=n=>{let f=schema.find(x=>x.toLowerCase()===n.toLowerCase());if(!f)throw Error('Unknown field: '+n);return f;};
 const val=t=>{t=t.trim();if(/^'[^']*'$|^"[^"]*"$/.test(t))return t.slice(1,-1);if(/^\$?(true|false)$/i.test(t))return /true/i.test(t);if(/^-?\d+(\.\d+)?$/.test(t))return Number(t);throw Error('Use a quoted string, boolean or number.');};
 for(const part of parts){
  let m;
  if((mode==='ps'&&(m=part.match(/^Where-Object\s+(\w+)\s+(-eq|-ne|-gt|-lt|-ge|-le|-like)\s+(.+)$/i)))||(mode==='kql'&&(m=part.match(/^where\s+(\w+)\s*(==|!=|>=|<=|>|<|contains)\s*(.+)$/i)))){
   const k=field(m[1]),op=m[2].toLowerCase(),v=val(m[3]);rows=rows.filter(r=>{let a=r[k];if(op==='-like'){let needle=String(v).toLowerCase();if(!needle.includes('*'))return String(a).toLowerCase()===needle;if(needle.startsWith('*')&&needle.endsWith('*'))return String(a).toLowerCase().includes(needle.slice(1,-1));if(needle.endsWith('*'))return String(a).toLowerCase().startsWith(needle.slice(0,-1));if(needle.startsWith('*'))return String(a).toLowerCase().endsWith(needle.slice(1));return false;}if(op==='contains')return String(a).toLowerCase().includes(String(v).toLowerCase());let aa=mode==='ps'&&typeof a==='string'?a.toLowerCase():a,bb=mode==='ps'&&typeof v==='string'?v.toLowerCase():v;return op==='-eq'||op==='=='?aa===bb:op==='-ne'||op==='!='?aa!==bb:op==='-gt'||op==='>'?aa>bb:op==='-lt'||op==='<'?aa<bb:op==='-ge'||op==='>='?aa>=bb:aa<=bb;});
  }else if((mode==='ps'&&(m=part.match(/^Select-Object\s+(?:-Property\s+)?([\w,\s]+)$/i)))||(mode==='kql'&&(m=part.match(/^project\s+([\w,\s]+)$/i)))){let ks=m[1].split(',').map(x=>field(x.trim()));rows=rows.map(x=>Object.fromEntries(ks.map(k=>[k,x[k]])));schema=ks;}
  else if((mode==='ps'&&(m=part.match(/^Sort-Object\s+(?:-Property\s+)?(\w+)(?:\s+(-Descending))?$/i)))||(mode==='kql'&&(m=part.match(/^(?:sort|order) by\s+(\w+)(?:\s+(asc|desc))?$/i)))){let k=field(m[1]),desc=/desc/i.test(m[2]||'');rows.sort((a,b)=>(a[k]<b[k]?-1:a[k]>b[k]?1:0)*(desc?-1:1));}
  else if((mode==='ps'&&(m=part.match(/^Group-Object\s+(?:-Property\s+)?(\w+)$/i)))||(mode==='kql'&&(m=part.match(/^summarize\s+(?:Count\s*=\s*)?count\(\)\s+by\s+(\w+)$/i)))){let k=field(m[1]),map=new Map();for(const row of rows)map.set(row[k],(map.get(row[k])||0)+1);let name=mode==='ps'?'Name':k;rows=[...map].map(([v,n])=>({[name]:v,Count:n}));schema=[name,'Count'];}
  else if(mode==='kql'&&(m=part.match(/^distinct\s+([\w,\s]+)$/i))){let ks=m[1].split(',').map(x=>field(x.trim())),map=new Map();for(const row of rows){let o=Object.fromEntries(ks.map(k=>[k,row[k]]));map.set(JSON.stringify(o),o);}rows=[...map.values()];schema=ks;}
  else if((mode==='ps'&&(m=part.match(/^Select-Object\s+-First\s+(\d+)$/i)))||(mode==='kql'&&(m=part.match(/^take\s+(\d+)$/i))))rows=rows.slice(0,Number(m[1]));
  else if(mode==='ps'&&/^Measure-Object$/i.test(part)||mode==='kql'&&/^count$/i.test(part)){rows=[{Count:rows.length}];schema=['Count'];}
  else if(mode==='ps'&&/^Get-Member$/i.test(part)){rows=schema.map(k=>({Name:k,MemberType:'NoteProperty',Type:typeof (rows[0]||{})[k]}));schema=['Name','MemberType','Type'];}
  else throw Error('Unsupported stage: '+part+'. Only the documented read-only subset is interpreted.');
  trace.push({stage:part,rows:rows.length,fields:schema.slice()});
 }return {ok:true,rows,trace};
 }catch(e){return {ok:false,error:String(e.message||e),rows:[],trace:[]};}}
