function apiValidate(v){const path=v.request==='GET /me'?{aud:'graph',kind:'delegated',perm:'User.Read'}:v.request==='GET /payroll'?{aud:'payroll',kind:v.kind,perm:v.kind==='application'?'Payroll.Read.All':'Payroll.Read'}:v.request==='POST /payroll/export'?{aud:'payroll',kind:v.kind,perm:v.kind==='application'?'Payroll.Export.All':'Payroll.Export'}:null;if(!path)return {status:404,reason:'Resource route is not in this fictional API.'};if(v.artifact!=='access'||v.issuer!=='approved'||v.signature!=='valid'||v.expiry!=='current'||v.audience!==path.aud)return {status:401,reason:'Authentication failed: '+(v.artifact!=='access'?'not an access token':v.issuer!=='approved'?'untrusted issuer':v.signature!=='valid'?'invalid signature':v.expiry!=='current'?'expired token':'wrong resource audience')};if(v.kind!==path.kind||!String(v.permission||'').split(/\s+/).includes(path.perm)||v.consent!=='granted')return {status:403,reason:'Authorization failed: required '+path.kind+' permission '+path.perm+' and grant.'};return {status:200,reason:'Modeled request permitted: appropriate validated access token and permission. Real endpoints may have additional requirements.'};}
const apiFields=[['request','Request',['GET /me','GET /payroll','POST /payroll/export']],['artifact','Token type',['access','id']],['issuer','Issuer',['approved','untrusted']],['audience','Audience',['graph','payroll']],['signature','Signature status',['valid','invalid']],['expiry','Expiry',['current','expired']],['kind','Permission type',['delegated','application']],['permission','Scope or role',['User.Read','Payroll.Read','Payroll.Export','Payroll.Read.All','Payroll.Export.All','None']],['consent','Grant',['granted','absent']]];
function apiDefault(){return Object.fromEntries(apiFields.map(x=>[x[0],x[2][0]]));}
function apiTaskPass(i,v,r){let t=apiTasks[i];if(!t||v.request!==t[1]||r.status!==t[5])return false;let good=v.artifact==='access'&&v.issuer==='approved'&&v.signature==='valid'&&v.expiry==='current'&&v.audience===t[2];let base=v.issuer==='approved'&&v.signature==='valid'&&v.kind===t[3]&&v.consent==='granted';if(i===1)return base&&v.artifact==='id'&&v.audience==='graph'&&v.expiry==='current'&&v.permission==='User.Read';if(i===2)return base&&v.artifact==='access'&&v.audience!=='graph'&&v.expiry==='current'&&v.permission==='User.Read';if(i===3)return base&&v.artifact==='access'&&v.audience==='graph'&&v.expiry==='expired'&&v.permission==='User.Read';if(i===4)return good&&base&&v.permission!=='User.Read';if(i===6)return good&&base&&v.permission==='Payroll.Read';return good&&base&&v.permission===t[4];}
function apiPage(){return layout(B('course/chapter/auth','← Return to authentication')+'<h1>MSAL and API request inspector</h1>'+P('Eight cases require the correct request, token purpose, issuer, signature status, audience, lifetime, scope or role and consent. This is a claim-validation model, not real signature verification, token issuance or MSAL execution.')+apiTasks.map((t,i)=>{let a=adv.api[i]||{},v=a.values||apiDefault();return sec((i+1)+'. '+t[0],P('Target: '+t[1]+' · expected HTTP '+t[5])+'<form class="adv-api" data-id="'+i+'">'+apiFields.map(([k,label,opts])=>'<label style="display:block;margin:8px 0">'+H(label)+' <select name="'+H(k)+'">'+opts.map(x=>'<option value="'+H(x)+'" '+(v[k]===x?'selected':'')+'>'+H(x)+'</option>').join('')+'</select></label>').join('')+'<button class="btn primary" type="submit">Send fictional request</button></form>'+(a.result?'<div class="un-result"><b>'+H('HTTP '+a.result.status+' · '+(a.pass?'PASS · intended boundary verified':'Target not yet met'))+'</b>'+P(a.result.reason)+'</div>':''));}).join(''));}
function igaInit(){return {time:0,hr:{id:'E-101',department:'Helpdesk',status:'prehire'},user:null,scim:false,groups:[],project:'none',extension:'ready',direct:false,guest:'none',guestExpiry:null,guestDirect:false,pim:'eligible',proof:false,approval:false,pimExpiry:null,logs:[],passed:{}};}
function igaAccess(x){return {helpdesk:!!x.user?.enabled&&x.groups.includes('Helpdesk'),finance:!!x.user?.enabled&&x.groups.includes('Finance'),project:!!x.user?.enabled&&(['assigned','review-denied'].includes(x.project)||x.direct),guestProject:x.guest==='assigned'||x.guestDirect,privileged:x.pim==='active'&&x.time<x.pimExpiry};}
function igaStep(x,a){let msg='';let log=t=>{msg=t;};switch(a){
 case 'hire':x.hr.status='active';log('HR source marks E-101 active. No target user created yet.');break;
 case 'import':if(x.hr.status!=='active'){log('No active employee in scope.');break;}if(!x.user)x.user={id:'U-101',employeeId:x.hr.id,department:x.hr.department,enabled:true};else{x.user.department=x.hr.department;x.user.enabled=true;}log('Matched stable employee ID; cloud record '+x.user.id+' read back.');break;
 case 'joiner':if(!x.user?.enabled){log('Joiner requires an enabled provisioned identity.');break;}x.groups=[x.user.department];x.scim=true;x.passed.joiner=igaAccess(x).helpdesk&&!igaAccess(x).finance;log('Birthright group evaluated; SCIM target provisioned.');break;
 case 'move':x.hr.department='Finance';log('HR department changed; target has not been updated.');break;
 case 'mover':if(!x.user?.enabled||x.user.department!==x.hr.department){log('Import the changed source attributes first.');break;}x.groups=[x.user.department];x.passed.mover=igaAccess(x).finance&&!igaAccess(x).helpdesk;log('Automatic assignment reevaluated: old department removed, current added.');break;
 case 'request':if(!x.user?.enabled){log('Enabled employee required.');break;}x.project='pending';log('Employee requested Project access; no assignment yet.');break;
 case 'approve':if(x.project!=='pending'){log('No pending employee request.');break;}x.project='approved';log('Request approved; delivery is still separate.');break;
 case 'fail-extension':x.extension='failed';log('Simulated extension dependency failure.');break;
 case 'restore-extension':x.extension='ready';log('Extension restored. Retry delivery explicitly.');break;
 case 'deliver':if(x.project!=='approved'||!x.user?.enabled){log('Approved request and enabled employee required.');break;}if(x.extension==='failed'){x.passed.extensionFailure=true;log('Delivery failed; approved request does not grant project access.');break;}x.project='assigned';x.passed.delivery=igaAccess(x).project;log('Resource assignment delivered.');break;
 case 'add-direct':x.direct=true;log('Independent direct employee project grant created in fixture.');break;
 case 'review-deny':if(x.project==='assigned'){x.project='review-denied';log('Review denial recorded; assignment still needs application.');}else log('No assigned package to review.');break;
 case 'apply-review':if(x.project!=='review-denied'){log('No recorded denial.');break;}x.project='removed';x.passed.alternate=x.direct;log('Package assignment removed; any independent direct grant survives.');break;
 case 'remove-direct':x.direct=false;log('Approved direct employee grant removed.');break;
 case 'leave':x.hr.status='terminated';log('HR termination event recorded; target not yet updated.');break;
 case 'leaver':if(x.hr.status!=='terminated'||!x.user){log('Terminated source and existing target required.');break;}x.user.enabled=false;x.groups=[];x.scim=false;x.project='removed';x.passed.leaver=!igaAccess(x).helpdesk&&!igaAccess(x).finance&&!x.scim;log('Disabled employee, removed birthright/package access and deprovisioned SaaS. Review alternate grants/retention separately.');break;
 case 'guest-request':x.guest='pending';log('Partner requests Project access; no entitlement.');break;
 case 'guest-approve':if(x.guest!=='pending'){log('No pending partner request.');break;}x.guest='assigned';x.guestExpiry=x.time+2;x.passed.guest=igaAccess(x).guestProject;log('Sponsor approval and modeled package delivery; expires in two time units.');break;
 case 'guest-direct':x.guestDirect=true;log('Independent direct guest grant added.');break;
 case 'guest-remove':x.guestDirect=false;log('Approved alternate guest grant removed.');break;
 case 'pim-request':if(x.pim!=='eligible'){log('Role must be eligible.');break;}x.pim='pending';x.proof=false;x.approval=false;log('Activation pending. No active privilege.');break;
 case 'pim-proof':if(x.pim!=='pending'){log('No pending activation.');break;}x.proof=true;log('Required authentication context proof satisfied in model.');break;
 case 'pim-approve':if(x.pim!=='pending'){log('No pending activation.');break;}x.approval=true;log('Independent approver authorizes request.');break;
 case 'pim-activate':if(x.pim!=='pending'||!x.proof||!x.approval){log('Activation denied: pending request, proof and approval all required.');break;}x.pim='active';x.pimExpiry=x.time+1;x.passed.pim=igaAccess(x).privileged;log('Role active for one time unit.');break;
 case 'tick':x.time++;if(x.pim==='active'&&x.time>=x.pimExpiry){x.pim='eligible';x.passed.pimExpiry=!igaAccess(x).privileged;}if(x.guest==='assigned'&&x.time>=x.guestExpiry){x.guest='expired';x.passed.guestExpiry=true;}log('Time advanced; applicable assignments expired. Alternate grants unchanged.');break;
 default:return false;}
 x.logs.push({time:x.time,action:a,message:msg});x.logs=x.logs.slice(-70);return true;}
const igaActions=[['HR source and lifecycle',[['hire','Record hire'],['import','Import / match employee'],['joiner','Run joiner tasks'],['move','Change HR department'],['mover','Run mover tasks'],['leave','Record termination'],['leaver','Run leaver tasks']]],['Employee entitlement',[['request','Request project'],['approve','Approve request'],['fail-extension','Inject extension fault'],['restore-extension','Restore extension'],['deliver','Deliver approved assignment'],['add-direct','Add separate direct grant'],['review-deny','Reviewer denies'],['apply-review','Apply review decision'],['remove-direct','Remove obsolete direct grant']]],['External partner',[['guest-request','Request partner access'],['guest-approve','Sponsor approves / assign'],['guest-direct','Add alternate guest grant'],['guest-remove','Remove alternate guest grant']]],['Privileged access',[['pim-request','Request activation'],['pim-proof','Satisfy required proof'],['pim-approve','Approver approves'],['pim-activate','Activate eligible role'],['tick','Advance one time unit']]]];
function igaPage(){let x=adv.iga||igaInit(),access=igaAccess(x);return layout(B('course/chapter/govern','← Return to governance')+'<h1>Identity governance operations workshop</h1>'+P('Four connected POC scenarios from the governance decks: HR lifecycle, employee packages, partner recertification and time-limited privilege. Actions modify fictional state, reject invalid transitions and produce evidence. No real tenant or Logic Apps connection.')+sec('Current modeled state',advTable([{Time:x.time,HR:x.hr.status,SourceDepartment:x.hr.department,CloudID:x.user?.id||'None',CloudDepartment:x.user?.department||'None',Enabled:x.user?.enabled??false,SCIM:x.scim,Groups:x.groups.join(', ')||'None',Project:x.project,Direct:x.direct,Guest:x.guest,GuestDirect:x.guestDirect,PIM:x.pim}])+advTable([access]))+igaActions.map(([label,items])=>sec(label,items.map(([a,t])=>'<button class="btn" data-action="adv-iga" data-id="'+H(a)+'">'+H(t)+'</button>').join(''))).join('')+sec('Verify all four scenarios',P('Import → joiner → HR mover → import → mover → request/approve → inject fault → delivery fails → restore → deliver → add direct → review/apply → remove direct → leave/leaver. Partner: request, approve, add direct, advance time twice, remove direct. PIM: request, attempt without proof, then proof and approval, activate, advance time.')+P('Evidence achieved: '+Object.keys(x.passed).filter(k=>x.passed[k]).join(', '))+P('Current resource decisions: '+JSON.stringify(access))+advTable(x.logs.slice().reverse())+'<button class="btn" data-action="adv-iga-reset">Reset fictional workshop</button>'));}
function agentInit(){return {blueprint:'none',identity:'none',permission:'none',requested:'none',grantedRead:false,fault:false,credential:'none',logs:[],passed:{}};}
function agentStep(x,a){let m='';switch(a){case 'blueprint-request':x.blueprint='pending';m='Blueprint requested, not approved.';break;case 'blueprint-approve':if(x.blueprint==='pending'){x.blueprint='approved';m='Blueprint approved.';}else m='No pending blueprint.';break;case 'identity-request':if(x.blueprint==='approved'){x.identity='pending';m='Identity requested under approved blueprint.';}else m='Approved blueprint required.';break;case 'identity-approve':if(x.identity==='pending'){x.identity='approved';m='Identity approved, provisioning still pending.';}else m='No pending identity.';break;case 'fault':x.fault=true;m='Modeled provisioning dependency unavailable.';break;case 'restore':x.fault=false;m='Dependency restored.';break;case 'provision':if(x.identity!=='approved'){m='Approved identity required.';break;}if(x.fault){x.passed.failure=true;m='Provisioning failed; no identity or credential issued.';break;}x.identity='provisioned';x.credential='managed (fictional)';x.passed.provision=true;m='Fictional identity provisioned.';break;case 'read-request':case 'write-request':if(x.identity!=='provisioned'){m='Provisioned identity required.';break;}x.requested=a==='read-request'?'Ticket.Read':'Ticket.Write';x.permission='pending';m='Permission request pending: '+x.requested;break;case 'approve-grant':if(x.permission!=='pending'){m='No pending grant.';break;}if(x.requested!=='Ticket.Read'){x.permission='rejected';x.passed.excess=true;m='Rejected: write exceeds approved read-only business scope.';break;}x.permission='granted';x.grantedRead=true;x.passed.read=true;m='Approved read-only grant applied.';break;case 'revoke':x.permission='revoked';x.grantedRead=false;x.credential='revoked';x.passed.revoked=true;m='Grant and modeled credential revoked.';break;default:return false;}x.logs.push({action:a,result:m});x.logs=x.logs.slice(-50);return true;}
function agentPage(){let x=adv.agent||agentInit();return layout(B('course/chapter/apps','← Return to applications')+'<h1>Agent identity approval and provisioning workshop</h1>'+P('Blueprint, identity and permission are separate records. The source mock service demonstrates separate approval and provisioning stages. This original model uses no external service or real credentials.')+sec('Current state',advTable([{Blueprint:x.blueprint,Identity:x.identity,Requested:x.requested,Grant:x.permission,Credential:x.credential,CanRead:x.identity==='provisioned'&&x.grantedRead&&x.credential!=='revoked',CanWrite:false}]))+sec('Run the approval lifecycle',[['blueprint-request','Request blueprint'],['blueprint-approve','Approve blueprint'],['identity-request','Request identity'],['identity-approve','Approve identity'],['fault','Inject provisioning fault'],['restore','Restore dependency'],['provision','Provision approved identity'],['write-request','Request excessive write'],['read-request','Request necessary read'],['approve-grant','Review and apply grant'],['revoke','Revoke approved access']].map(([a,t])=>'<button class="btn" data-action="adv-agent" data-id="'+a+'">'+H(t)+'</button>').join(''))+sec('Evidence',P('Achieved: '+Object.keys(x.passed).filter(k=>x.passed[k]).join(', '))+advTable(x.logs.slice().reverse())+'<button class="btn" data-action="adv-agent-reset">Reset workshop</button>'));}
function advancedUnit(c,i){let rows=advancedLessons.filter(x=>x[0]===c[0]&&x[1]===i);return rows.length?'<section class="un-depth"><h3>Source-based applied engineering</h3>'+rows.map(x=>detail(x[2],P(x[3])+P(x[4])+B(x[5],'Practice and verify now'))).join('')+'</section>':'';}
function advancedSummary(){return sec('Additional repository-derived practice',P('60 further textual assets retrieved and four governance decks (256 slides) inspected via extracted slide text. The workbenches below are original local models, not live Microsoft services.')+B('course/lab/query','Composable PowerShell and KQL workbench')+B('course/lab/api-inspector','MSAL and API request inspector')+B('course/lab/iga','Four governance POC scenarios')+B('course/lab/agent','Agent approval and provisioning'));}
function advancedAudit(){let checks=[],ck=(name,pass)=>checks.push({name,pass:!!pass});ck('60 further source files and four decks',advancedSources.files.length===60&&advancedSources.decks.length===4&&advancedSources.decks.reduce((n,x)=>n+x[3],0)===256);ck('12 applied lessons have valid units',advancedLessons.length===12&&advancedLessons.every(x=>teachingUnits[x[0]]?.[x[1]]));for(const [i,t] of queryTasks.entries()){let r=queryEval(t[0],t[2]);ck('query task '+i+' correct output',r.ok&&t[4](r.rows));}ck('query composed alternative accepted',queryEval('ps','Get-MgUser | Where-Object Department -eq "Finance" | Sort-Object DisplayName -Descending | Select-Object DisplayName').rows[0]?.DisplayName==='Sam Patel');ck('query arbitrary shell rejected',!queryEval('ps','Remove-Item C:\\').ok);ck('query invalid property rejected',!queryEval('kql','SigninLogs | where fake == "x"').ok);ck('query empty output valid',queryEval('kql','SigninLogs | where ResultType == "999"').ok&&queryEval('kql','SigninLogs | where ResultType == "999"').rows.length===0);
 let a=apiDefault();ck('valid delegated Graph',apiValidate(a).status===200&&apiTaskPass(0,a,apiValidate(a)));for(const [i,field,val] of [[1,'artifact','id'],[2,'audience','payroll'],[3,'expiry','expired'],[4,'permission','None']]){let v={...a,[field]:val},r=apiValidate(v);ck('API case '+i,apiTaskPass(i,v,r));}for(const [i,req,kind,perm] of [[5,'GET /payroll','delegated','Payroll.Read'],[6,'POST /payroll/export','delegated','Payroll.Read'],[7,'GET /payroll','application','Payroll.Read.All']]){let v={...a,request:req,audience:'payroll',kind,permission:perm};ck('API case '+i,apiTaskPass(i,v,apiValidate(v)));}ck('wrong reason cannot pass',!apiTaskPass(1,{...a,signature:'invalid'},apiValidate({...a,signature:'invalid'})));
 let x=igaInit();igaStep(x,'joiner');ck('joiner requires target',!x.user&&!x.scim);for(const e of ['hire','import','joiner','move','import','mover','request','approve','fail-extension','deliver'])igaStep(x,e);ck('approved extension failure not granted',x.passed.joiner&&x.passed.mover&&x.passed.extensionFailure&&!igaAccess(x).project);for(const e of ['restore-extension','deliver','review-deny'])igaStep(x,e);ck('review decision alone preserves assignment',igaAccess(x).project);for(const e of ['add-direct','apply-review'])igaStep(x,e);ck('direct access survives review removal',x.passed.delivery&&x.passed.alternate&&igaAccess(x).project);igaStep(x,'remove-direct');ck('alternate grant removed',!igaAccess(x).project);for(const e of ['leave','leaver','guest-request','guest-approve','guest-direct','tick','tick'])igaStep(x,e);ck('leaver and guest expiry',x.passed.leaver&&x.passed.guestExpiry&&igaAccess(x).guestProject);igaStep(x,'guest-remove');ck('guest actual denial',!igaAccess(x).guestProject);for(const e of ['pim-request','pim-activate'])igaStep(x,e);ck('PIM no premature activation',!igaAccess(x).privileged);for(const e of ['pim-proof','pim-approve','pim-activate'])igaStep(x,e);ck('PIM approved activation',igaAccess(x).privileged);igaStep(x,'tick');ck('PIM expiration',x.passed.pimExpiry&&!igaAccess(x).privileged);
 let y=agentInit();agentStep(y,'identity-request');ck('agent blueprint dependency',y.identity==='none');for(const e of ['blueprint-request','blueprint-approve','identity-request','identity-approve','fault','provision'])agentStep(y,e);ck('agent provision failure',y.passed.failure&&y.identity==='approved'&&y.credential==='none');for(const e of ['restore','provision','write-request','approve-grant'])agentStep(y,e);ck('agent excessive grant rejected',y.permission==='rejected'&&y.passed.excess);for(const e of ['read-request','approve-grant','write-request','approve-grant'])agentStep(y,e);ck('rejected new grant does not revoke prior grant',y.grantedRead&&y.permission==='rejected');agentStep(y,'revoke');ck('agent approved and revoked',y.passed.read&&y.passed.revoked&&y.permission==='revoked');for(const fn of [queryPage,apiPage,igaPage,agentPage])ck('workbench renders '+fn.name,fn().length>1000);return checks;}


