function granularOptions2(l,k){const a=granularState(l[0]),opts=k===0?l[10]:l[12],shift=(granularLessons.indexOf(l)+k)%3,rot=[...opts.slice(shift),...opts.slice(0,shift)];return rot.map((t,i)=>{let value=(i+shift)%3;return '<button class="btn '+(a.picks[k]===value?'primary':'')+'" data-action="granular-pick" data-id="'+H(l[0])+'" data-key="'+k+'" data-value="'+value+'" '+(a.locked?'disabled':'')+'>'+H(t)+'</button>';}).join('');}
