s.ms.gaps=s.ms.gaps||{};s.ms.labTasks=s.ms.labTasks||{};
const gapState=id=>s.ms.gaps[id]||{values:{},first:null,last:null,runs:0,baseline:false,fault:false,recovered:false,note:''};
const gapRoute=id=>'course/skill-lab/'+id;
function gapEval(l,v){return l[4].map(x=>({name:x[0],pass:x[1].every(k=>{const f=l[3].find(y=>y[0]===k);return Number(v[k])===f[4]}),why:x[2]}));}
function gapRun(l,a){if(l[3].some(f=>!Number.isInteger(a.values[f[0]])||a.values[f[0]]<0||a.values[f[0]]>=f[3].length))return false;let r=gapEval(l,a.values),pass=r.every(x=>x.pass);a.runs++;a.last={pass,results:r};if(a.first===null)a.first=pass;if(pass){if(a.baseline&&a.fault)a.recovered=true;a.baseline=true;}else if(a.baseline){const f=l[3].find(f=>f[0]===l[5]);if(a.values[f[0]]!==f[4]&&l[3].filter(x=>x[0]!==l[5]).every(x=>a.values[x[0]]===x[4]))a.fault=true;}return true;}
const gapDone=l=>{const a=gapState(l[0]);return a.baseline&&a.fault&&a.recovered&&a.last?.pass;};
function gapProgress(){return P('Dedicated objective labs: '+gapLabs.filter(gapDone).length+'/'+gapLabs.length+' have current passing configuration, demonstrated targeted fault and recovery. First-attempt configuration outcomes remain recorded.');}
function gapPage(id){const l=gapMap.get(id),r=depthGet(id);if(!l||!r)return layout('<h1>Skill lab not found</h1>'+B('course/coverage','Return to objectives'));const a=gapState(id),ready=l[3].every(f=>Number.isInteger(a.values[f[0]]));return layout(B('course/chapter/'+r.chapter,'← Return to chapter')+'<h1>'+H(id+' · '+l[1])+'</h1>'+P(l[2])+P('Original local configuration model. Choose values, verify all outcomes, then introduce the named isolated fault and recover. A passed model is not a real Microsoft configuration. No real tenant, DNS, credentials, licensing or resources are changed.')+l[3].map(f=>sec(f[1],P(f[2])+f[3].map((x,j)=>'<button class="btn '+(a.values[f[0]]===j?'primary':'')+'" data-action="gap-config" data-id="'+H(id)+'" data-key="'+H(f[0])+'" data-value="'+j+'">'+H(x)+'</button>').join(''))).join('')+sec('Verify configuration and troubleshoot','<button class="btn primary" data-action="gap-run" data-id="'+H(id)+'" '+(ready?'':'disabled')+'>Run verification</button>'+P('Runs: '+a.runs+' · first configuration: '+(a.first===null?'not tested':a.first?'passed':'needs review'))+(a.last?a.last.results.map(x=>'<div class="un-result"><b>'+H((x.pass?'PASS · ':'FAIL · ')+x.name)+'</b>'+P(x.why)+'</div>').join(''):P('Select every field and run verification. Changes invalidate current results.'))+P('Fault injection: after establishing a passing configuration, change only '+l[3].find(f=>f[0]===l[5])[1]+', run verification, explain the failed boundary, restore it and verify again.')+P('Baseline: '+(a.baseline?'verified':'pending')+' · isolated fault: '+(a.fault?'verified':'pending')+' · recovery: '+(gapDone(l)?'verified':'pending'))+'<form class="un-gap-note" data-id="'+H(id)+'"><label><b>Explain the failing field and why restoring it fixed the result</b><textarea name="note" aria-label="Evidence">'+H(a.note||'')+'</textarea></label><button type="submit" class="btn">Save explanation</button></form><button class="btn" data-action="gap-reset" data-id="'+H(id)+'">Reset this exercise</button>')+P(r.verification)+B('course/coverage','Return to objective crosswalk'));}
const labTaskRows=repoTraining.sc.flatMap((a,i)=>a[4].map((name,j)=>({id:i+'-'+j,lab:i,title:name})));
const labTaskMap=new Map(labTaskRows.map(x=>[x.id,x]));
const labTaskStatuses=['not-started','studied','paper-practice','real-tenant-self-reported','blocked-by-prerequisites'];
function labTaskState(id){return s.ms.labTasks[id]||{status:'not-started',note:''};}
function labTaskStats(){let n={total:labTaskRows.length,studied:0,paper:0,real:0,blocked:0};for(const x of labTaskRows){let a=labTaskState(x.id);if(a.status==='studied')n.studied++;if(a.status==='paper-practice')n.paper++;if(a.status==='real-tenant-self-reported')n.real++;if(a.status==='blocked-by-prerequisites')n.blocked++;}return n;}
function labTaskCard(n){const rows=labTaskRows.filter(x=>x.lab===n);return detail('Task-by-task evidence record · '+rows.length+' upstream headings',P('Use this ledger to distinguish study, paper practice, prerequisite blockers and self-reported authorized real-tenant work. A heading can contain multiple steps; this is not proof that every step is reproduced. Do not enter passwords, tokens, personal data or secret values.')+rows.map(x=>{let a=labTaskState(x.id);return '<form class="un-lab-task" data-id="'+H(x.id)+'"><div class="un-word"><b>'+H(x.title)+'</b>'+taskPracticeCard(x)+'<label style="display:block">Evidence status <select name="status">'+labTaskStatuses.map(v=>'<option value="'+v+'" '+(a.status===v?'selected':'')+'>'+H(v.replace(/-/g,' '))+'</option>').join('')+'</select></label><label style="display:block">Evidence or blocker<textarea name="note" aria-label="Task evidence">'+H(a.note||'')+'</textarea></label><button type="submit" class="btn">Save task record</button></div></form>';}).join(''));}
function labTaskSummary(){const n=labTaskStats();return sec('Official lab task evidence',P(n.total+' retrieved upstream task/exercise headings across 29 lab files. Studied: '+n.studied+'; paper practice: '+n.paper+'; self-reported real tenant: '+n.real+'; blocked: '+n.blocked+'.')+P('Every heading has a related objective model or an explicit external prerequisite. '+labTaskRows.filter(x=>taskPractice(x).blocked).length+' headings require external setup or actions not reproduced here. Model links are supporting practice, not exact task reproduction. Self-reported records are not automatically credited as simulator passes or verified real-tenant competency.')+B('course/lab-evidence','Open lab evidence tracker'));}
function labEvidencePage(){return layout(B('course/evidence','← Return to learning evidence')+'<h1>Official lab task evidence tracker</h1>'+sourceStepSummary()+labTaskSummary()+repoTraining.labs.map((l,i)=>sec('Lab '+String(i).padStart(2,'0')+' · '+l[1],B('course/chapter/'+l[0],'Study related chapter')+repoSourceButton(repoSourceMap.get('sc-'+i),'Read pinned source')+labTaskCard(i))).join(''));}
function gapAudit(){let checks=[],ck=(name,pass)=>checks.push({name,pass:!!pass});ck('all 98 objective-specific labs',gapLabs.length===98&&new Set(gapLabs.map(x=>x[0])).size===98&&depthRows.every(r=>gapMap.has(r.id)));for(const l of gapLabs){ck(l[0]+' valid objective and dependencies',!!depthGet(l[0])&&l[3].length>=3&&l[3].every(f=>f[3][f[4]]!==undefined)&&l[4].every(t=>t[1].every(k=>l[3].some(f=>f[0]===k))));let good=Object.fromEntries(l[3].map(f=>[f[0],f[4]])),a={values:{},first:null,last:null,runs:0,baseline:false,fault:false,recovered:false};ck(l[0]+' incomplete config blocked',!gapRun(l,a));a.values={...good};ck(l[0]+' baseline evaluated',gapRun(l,a)&&a.last.pass&&a.baseline&&!a.recovered);for(const f of l[3]){const v={...good,[f[0]]:(f[4]+1)%f[3].length};ck(l[0]+' detect wrong '+f[0],gapEval(l,v).some(t=>!t.pass));}let f=l[3].find(f=>f[0]===l[5]);a.values[f[0]]=(f[4]+1)%f[3].length;ck(l[0]+' isolated fault evaluated',gapRun(l,a)&&!a.last.pass&&a.fault);a.values={...good};ck(l[0]+' recovery evaluated',gapRun(l,a)&&a.last.pass&&a.recovered);ck(l[0]+' renders specific fields',gapPage(l[0]).includes(H(l[2]))&&gapPage(l[0]).includes('Run verification')&&gapPage(l[0]).includes('Fault injection'));}ck('all upstream task headings indexed',labTaskRows.length===repoTraining.sc.reduce((n,x)=>n+x[4].length,0)&&new Set(labTaskRows.map(x=>x.id)).size===labTaskRows.length);ck('all task cards rendered',repoTraining.labs.every((l,i)=>labTaskCard(i).match(/class="un-lab-task"/g)?.length===repoTraining.sc[i][4].length));ck('tracker page route content',labEvidencePage().includes('Official lab task evidence tracker'));return checks;}


