function taskPractice(x){const id=taskSkillMap[x.lab]?.[Number(x.id.split('-')[1])],r=depthGet(id);return {id,blocked:id==='BLOCK',skill:r?.title||'',evidence:taskEvidenceSpecific[x.id]||(r?'For this task, use the exact source instructions for the operation; compare the related model with the source requirement. Capture the relevant input, expected result and actual observation. '+r.verification:'Requires authorized external setup; use the lab walkthrough to document prerequisites and the intended verification. No cloud activation or live change is performed.')};}
function taskPracticeCard(x){let p=taskPractice(x);return '<div class="un-result"><b>'+H(p.blocked?'External prerequisite · not reproduced':'Related objective model · '+p.id+' '+p.skill)+'</b>'+P(p.evidence)+(p.blocked?'':'<button type="button" class="btn" data-route="'+H(gapRoute(p.id))+'">Open related configuration and recovery model</button>'+P('Related model status: '+(gapDone(gapMap.get(p.id))?'baseline/fault/recovery verified':'not yet verified')+'. This does not prove the exact official task was completed.'))+'</div>';}
