/* Local progress backup/restore. Only three documented learning keys are affected. No credentials, server calls or account data. */
const backupKeys=[key,'entra-v16-study-v1','entra-v17-study-v1'],backupRollbackKey='entra-unified-restore-rollback-v1';
let backupPending=null,backupMessage='';
const plainRecord=x=>x!==null&&typeof x==='object'&&!Array.isArray(x)&&Object.getPrototypeOf(x)===Object.prototype;
function backupSafeTree(x,level=0){if(level>40)throw Error('Backup nesting is too deep.');if(x===null||typeof x==='boolean'||typeof x==='number'&&Number.isFinite(x)||typeof x==='string'&&x.length<=1000000)return;if(Array.isArray(x)){if(x.length>20000)throw Error('Backup array is too large.');x.forEach(y=>backupSafeTree(y,level+1));return;}if(!plainRecord(x))throw Error('Invalid backup value.');let ks=Object.keys(x);if(ks.length>20000)throw Error('Backup object is too large.');for(const k of ks){if(['__proto__','prototype','constructor'].includes(k))throw Error('Unsafe object key.');backupSafeTree(x[k],level+1);}}
function backupMap(x,name){if(!plainRecord(x))throw Error(name+' must be an object.');}
function backupMapEntries(x,name,predicate){backupMap(x,name);if(!Object.values(x).every(predicate))throw Error(name+' contains invalid values.');}
function backupValidate(text){try{if(typeof text!=='string'||!text.trim()||text.length>4000000)throw Error('Select a nonempty JSON backup under 4 million characters.');const b=JSON.parse(text);backupSafeTree(b);if(!plainRecord(b)||!['unified-identity-learning-v1','unified-identity-learning-v2'].includes(b.schema))throw Error('Not a supported Identity Academy backup.');const u=b.unified;backupMap(u,'Unified state');if(!chapter(u.chapter))throw Error('Unrecognized chapter.');backupMapEntries(u.answers,'Chapter answers',v=>Number.isInteger(v)&&v>=0&&v<8);backupMapEntries(u.notes,'Chapter notes',v=>typeof v==='string');backupMapEntries(u.opened,'Opened chapters',v=>typeof v==='boolean');if(u.master!==undefined)backupMapEntries(u.master,'Mastery records',plainRecord);if(u.ms!==undefined){backupMap(u.ms,'Microsoft practice state');for(const k of ['sim','commands','depth','granular','gaps','labTasks','domainExam','sourceSteps'])if(u.ms[k]!==undefined)backupMapEntries(u.ms[k],k,plainRecord);for(const k of ['exam','repo','advanced','transfer','glossary'])if(u.ms[k]!==undefined)backupMap(u.ms[k],k);
 const m=u.ms;if(m.tenantEvidence!==undefined){backupMap(m.tenantEvidence,'Tenant evidence');backupMap(m.tenantEvidence.runs,'Tenant read records');backupMapEntries(m.tenantEvidence.portfolio,'Tenant portfolios',validatePortfolio);if(typeof m.tenantEvidence.challenge!=='string')throw Error('Invalid challenge.');}for(const r of Object.values(m.sourceSteps||{})){if(!stepStates.includes(r.status)||typeof r.note!=='string')throw Error('Invalid source step record.');}if(m.directoryOps!==undefined){backupMap(m.directoryOps,'Directory workshop');if(!Array.isArray(m.directoryOps.users)||!Array.isArray(m.directoryOps.roles)||!Array.isArray(m.directoryOps.apps)||!Array.isArray(m.directoryOps.logs)||!plainRecord(m.directoryOps.groups)||!plainRecord(m.directoryOps.checks))throw Error('Invalid directory workshop.');}for(const r of Object.values(m.gaps||{})){backupMap(r.values,'Lab field values');if(!Number.isInteger(r.runs)||r.runs<0||typeof r.baseline!=='boolean'||typeof r.fault!=='boolean'||typeof r.recovered!=='boolean')throw Error('Invalid lab run history.');if(r.last!==null&&r.last!==undefined&&(!plainRecord(r.last)||!Array.isArray(r.last.results)))throw Error('Invalid lab verification result.');}
 for(const r of Object.values(m.labTasks||{})){if(!labTaskStatuses.includes(r.status)||typeof r.note!=='string')throw Error('Invalid task evidence status.');}
 if(m.exam)backupMap(m.exam.answers,'Assessment answers');
 if(m.repo){backupMapEntries(m.repo.notes||{},'Repository notes',v=>typeof v==='string');backupMapEntries(m.repo.read||{},'Repository reading flags',v=>typeof v==='boolean');}
 if(m.advanced){backupMap(m.advanced.queries||{},'Query results');backupMap(m.advanced.api||{},'API results');if(m.advanced.iga!==null&&m.advanced.iga!==undefined){backupMap(m.advanced.iga,'Governance workshop');if(!Array.isArray(m.advanced.iga.groups)||!Array.isArray(m.advanced.iga.logs))throw Error('Invalid governance workshop records.');}if(m.advanced.agent!==null&&m.advanced.agent!==undefined){backupMap(m.advanced.agent,'Agent workshop');if(!Array.isArray(m.advanced.agent.logs))throw Error('Invalid agent workshop records.');}}
 const exams=[...Object.values(m.transfer?.forms||{}),...Object.values(m.domainExam||{})];for(const r of exams){backupMap(r,'Assessment attempt');backupMap(r.picks,'Assessment picks');if(!Array.isArray(r.attempts)||typeof r.submitted!=='boolean'||r.submitted&&(!plainRecord(r.first)||!plainRecord(r.last)))throw Error('Invalid assessment history.');}
 }
 for(const [n,z,ks] of [['Engineering',b.engineering,['answers','cases','steps','notes']],['Hybrid',b.hybrid,['answers','cases','stages','cards','notes']]]){backupMap(z,n);for(const k of ks)backupMap(z[k],n+' '+k);}
 backupMap(b.hybrid.lab,'Hybrid lab');if(!Array.isArray(b.hybrid.lab.logs))throw Error('Invalid hybrid logs.');
 return {ok:true,data:b,summary:{chapter:chapter(u.chapter)[1],answers:Object.keys(u.answers).length,notes:Object.keys(u.notes).length,skillRecords:Object.keys(u.ms?.depth||{}).length,labRecords:Object.keys(u.ms?.gaps||{}).length,taskRecords:Object.keys(u.ms?.labTasks||{}).length,exportedAt:typeof b.exportedAt==='string'?b.exportedAt:'unknown'}};
 }catch(e){return {ok:false,error:String(e.message||e)};}}
function currentBackup(){return {schema:'unified-identity-learning-v2',exportedAt:new Date().toISOString(),unified:s,engineering:v16.state,hybrid:v17.state};}
function backupWrite(b,store){let checked=backupValidate(JSON.stringify(b));if(!checked.ok)return checked;let before=backupKeys.map(k=>store.getItem(k)),oldRollback=store.getItem(backupRollbackKey);try{const rollback=JSON.stringify(currentBackup());store.setItem(backupRollbackKey,rollback);const data=checked.data;[data.unified,data.engineering,data.hybrid].forEach((v,i)=>store.setItem(backupKeys[i],JSON.stringify(v)));return {ok:true};}catch(e){try{before.forEach((v,i)=>v===null?store.removeItem(backupKeys[i]):store.setItem(backupKeys[i],v));if(oldRollback===null)store.removeItem(backupRollbackKey);else store.setItem(backupRollbackKey,oldRollback);}catch(rollbackError){return {ok:false,error:'Restore failed and browser storage rollback also failed. Use your downloaded backup. '+String(rollbackError.message||rollbackError)};}return {ok:false,error:'Restore failed; prior stored values restored. '+String(e.message||e)};}}
function backupPage(){let check=backupPending,rollback=false;try{rollback=!!localStorage.getItem(backupRollbackKey);}catch(e){}return layout(B('course/evidence','← Learning evidence')+'<h1>Backup and restore learning progress</h1>'+P('Progress is stored in this browser. Export regularly, especially before clearing browser data or moving to another device. This backup covers the unified course and the V16/V17 learning records only. Earlier portal simulator data has its own backup. No file is uploaded to a server.')+sec('1. Export current learning progress','<button class="btn primary" data-action="un-export">Download current JSON backup</button>'+P('Keep this file private: it may contain your written study notes. Do not put credentials or sensitive tenant data in notes.'))+sec('2. Preview a backup','<form class="un-backup-preview"><label>Choose exported JSON file<input type="file" name="backupFile" accept=".json,application/json"></label><label>Or paste backup JSON<textarea name="backupText" aria-label="Backup JSON"></textarea></label><button class="btn primary" type="submit">Validate and preview</button></form>'+(rollback?'<button class="btn" data-action="backup-rollback-preview">Preview previous local restore snapshot</button>':'')+(backupMessage?'<div class="un-result">'+P(backupMessage)+'</div>':'')+(check?.ok?'<div class="un-result"><b>Validated structure · preview only</b>'+advTable([check.summary])+P('This is a replacement of the three learning states, not a merge. Current progress will be saved in a local rollback snapshot before replacement. Download your current backup first. Validation checks structure, not authenticity or competency.')+'<button class="btn primary" data-action="backup-apply">Replace local learning progress with this backup</button><button class="btn" data-action="backup-cancel">Cancel preview</button></div>':''))+sec('3. Restore and verify',P('A successful restore reloads the academy so all modules read the restored state. The previous snapshot is available locally until the next restore. If local browser storage is unavailable or full, the restore fails rather than silently proceeding.')));}
async function backupPreviewForm(form){try{const file=form.querySelector('[name=backupFile]')?.files?.[0],pasted=String(form.querySelector('[name=backupText]')?.value||'');if(file&&file.size>4000000)throw Error('Backup file is too large.');backupPending=backupValidate(file?await file.text():pasted);backupMessage=backupPending.ok?'Preview ready. Nothing has been restored.':backupPending.error;if(current()==='course/backup')render();}catch(e){backupPending=null;backupMessage=String(e.message||e);if(current()==='course/backup')render();}}
function backupAudit(){let out=[],ck=(name,pass)=>out.push({name,pass:!!pass}),b=JSON.parse(JSON.stringify(currentBackup())),valid=backupValidate(JSON.stringify(b));ck('current backup valid',valid.ok);ck('old v1 backup accepted',backupValidate(JSON.stringify({...b,schema:'unified-identity-learning-v1'})).ok);ck('invalid JSON rejected',!backupValidate('{').ok);ck('unsafe key rejected',!backupValidate('{"schema":"unified-identity-learning-v2","__proto__":{}}').ok);ck('malformed state rejected',!backupValidate(JSON.stringify({...b,unified:{...b.unified,answers:[]}})).ok);ck('unsupported schema rejected',!backupValidate(JSON.stringify({...b,schema:'other'})).ok);
 let m=new Map(backupKeys.map(k=>[k,'prior-'+k])),mem={getItem:k=>m.get(k)??null,setItem:(k,v)=>m.set(k,v),removeItem:k=>m.delete(k)};let r=backupWrite(b,mem);ck('atomic restore writes three keys and rollback',r.ok&&backupKeys.every(k=>JSON.parse(mem.getItem(k)))&&!!mem.getItem(backupRollbackKey));let before=backupKeys.map(k=>mem.getItem(k)),once=true;let failing={...mem,setItem:(k,v)=>{if(k===backupKeys[1]&&once){once=false;throw Error('simulated quota');}mem.setItem(k,v);}};r=backupWrite(b,failing);ck('write failure restores prior values',!r.ok&&backupKeys.every((k,i)=>mem.getItem(k)===before[i]));ck('backup page renders preview and export',backupPage().includes('Validate and preview')&&backupPage().includes('Download current JSON backup'));return out;}


