s.ms.sourceSteps=s.ms.sourceSteps||{};
const stepStates=['not-started','read','paper-verified','real-self-reported','blocked'];
function stepRecord(id){return s.ms.sourceSteps[id]||{status:'not-started',note:''};}
function stepStats(lab){let rows=sourceSteps.filter(x=>lab===undefined||x.lab===lab),a={total:rows.length,read:0,paper:0,real:0,blocked:0};for(const x of rows){let v=stepRecord(x.id).status;if(v==='read')a.read++;if(v==='paper-verified')a.paper++;if(v==='real-self-reported')a.real++;if(v==='blocked')a.blocked++;}return a;}
function stepPage(n){if(!Number.isInteger(n)||n<0||n>=29)n=0;const f=repoSourceMap.get('sc-'+n),rows=sourceSteps.filter(x=>x.lab===n),st=stepStats(n);let headingGroups=[-1,...repoTraining.sc[n][4].map((_,i)=>i)];return layout(B('course/lab-evidence','← Official lab evidence')+'<h1>Source-step workbook · Lab '+String(n).padStart(2,'0')+'</h1>'+P(repoTraining.labs[n][1])+P('This indexes numbered Markdown instruction lines, not all prose, tables, nested material or screenshots. Each source-line link opens the exact pinned original instruction. These are self-reported reading/practice records; no real tenant execution is implied. Never copy credentials, tokens, secret values or personal data into notes.')+P('Indexed '+st.total+' · read '+st.read+' · paper evidence '+st.paper+' · self-reported real '+st.real+' · blocked '+st.blocked)+repoSourceButton(f,'Open full pinned lab')+sec('Select laboratory',repoTraining.labs.map((l,i)=>B('course/lab-steps/'+i,String(i).padStart(2,'0')+' '+l[1])).join(''))+headingGroups.map(j=>{let a=rows.filter(x=>x.heading===j);if(!a.length)return '';return detail(j===-1?'Other numbered instructions':repoTraining.sc[n][4][j],a.map(x=>{let v=stepRecord(x.id);return '<form class="un-source-step" data-id="'+H(x.id)+'"><div class="un-word"><b>Source line '+x.line+' · numbered item '+x.number+'</b><p>'+A(repoGit(f)+'#L'+x.line,'Open exact numbered instruction')+'</p><label>Status <select name="status">'+stepStates.map(k=>'<option value="'+k+'" '+(v.status===k?'selected':'')+'>'+H(k.replace(/-/g,' '))+'</option>').join('')+'</select></label><label>Input, expected result, observed evidence or prerequisite<textarea name="note">'+H(v.note)+'</textarea></label><button type="submit" class="btn">Save step record</button></div></form>';}).join(''));}).join(''));}
function sourceStepSummary(){let x=stepStats();return sec('Numbered instruction workbook',P(x.total+' numbered source lines indexed in all 29 pinned labs. Each record links to its original line. '+x.paper+' paper-verified, '+x.real+' real-self-reported, '+x.blocked+' blocked.')+B('course/lab-steps/0','Open step-level workbook'));}
function directoryInit(){return {clock:0,users:[{id:'U1',upn:'alex@contoso.example',department:'Finance',enabled:true,deleted:false,guest:false,accepted:true,directLicense:false},{id:'U2',upn:'casey@contoso.example',department:'IT',enabled:true,deleted:false,guest:false,accepted:true,directLicense:false}],groups:{finance:{id:'G1',rule:'Finance',licensed:true},project:{id:'G2',members:[]}},roles:[],apps:[],seats:1,allowUserApps:false,logs:[],checks:{}};}
function directoryMembership(x,id){let u=x.users.find(u=>u.id===id);return {finance:!!u&&!u.deleted&&u.department===x.groups.finance.rule,project:!!u&&!u.deleted&&x.groups.project.members.includes(id)};}
function directoryLicenses(x){let list=x.users.filter(u=>!u.deleted&&(u.directLicense||(x.groups.finance.licensed&&directoryMembership(x,u.id).finance)));return list.sort((a,b)=>Number(b.directLicense)-Number(a.directLicense)||a.id.localeCompare(b.id)).map((u,i)=>({id:u.id,source:u.directLicense?'direct':'group',status:i<x.seats?'assigned':'capacity-error'}));}
function directoryAccess(x,id,operation){let u=x.users.find(y=>y.id===id);if(!u||u.deleted||!u.enabled)return {allow:false,reason:'Account missing, disabled or deleted'};if(u.guest&&!u.accepted)return {allow:false,reason:'Guest redemption not established'};if(operation==='app-create'){let allow=x.allowUserApps||x.roles.some(r=>r.id===id&&r.role==='Application Administrator');return {allow,reason:allow?'Applicable role/default permits modeled create':'No applicable app creation authority'};}if(operation==='project-read'){let allow=directoryMembership(x,id).project;return {allow,reason:allow?'Project group grants modeled Reader':'No project grant'};}if(operation==='licensed-workload'){let allow=directoryLicenses(x).some(y=>y.id===id&&y.status==='assigned');return {allow,reason:allow?'Modeled product seat assigned':'No available modeled product entitlement'};}return {allow:false,reason:'Unknown operation'};}
const directoryOps=[['add','Create new employee U3'],['grant-role','Assign U3 app administrator'],['create-app','Attempt app creation as U3'],['remove-role','Remove U3 app administrator'],['move','Change U3 department to Finance'],['direct-license','Assign U3 direct license'],['remove-direct-license','Remove U3 direct license'],['expand-seats','Set fictional existing capacity to 3'],['invite','Invite external U4'],['guest-project','Assign U4 project reader group'],['redeem','Redeem U4 invitation'],['guest-disable','Disable U4'],['guest-enable','Re-enable U4'],['guest-remove','Remove U4 project grant'],['delete','Soft-delete U3'],['restore','Restore U3']];
function directoryStep(x,a){let msg='',u=x.users.find(y=>y.id==='U3'),g=x.users.find(y=>y.id==='U4');switch(a){
case 'add':if(u){msg='U3 exists (possibly deleted); do not duplicate identity.';break;}x.users.push({id:'U3',upn:'jordan@contoso.example',department:'IT',enabled:true,deleted:false,guest:false,accepted:true,directLicense:false});x.checks.created=true;msg='Created U3, independent object ID and UPN.';break;
case 'grant-role':if(!u||u.deleted||!u.enabled){msg='No active U3.';break;}if(!x.roles.some(r=>r.id==='U3'))x.roles.push({id:'U3',role:'Application Administrator'});msg='Assigned role; app operation still needs a test.';break;
case 'create-app':{let r=directoryAccess(x,'U3','app-create');if(r.allow){x.apps.push({id:'APP'+(x.apps.length+1),owner:'U3'});x.checks.allowed=true;msg='Allowed: created fictional app.';}else{if(u&&!u.deleted&&u.enabled){if(x.checks.allowed)x.checks.revoked=true;else x.checks.deniedBefore=true;}msg='Denied: '+r.reason;}break;}
case 'remove-role':x.roles=x.roles.filter(r=>r.id!=='U3');msg='Removed assignment; retest operation.';break;
case 'move':if(!u||u.deleted){msg='Create/restore U3 first.';break;}u.department='Finance';msg='Source attribute changed; dynamic membership recalculated.';if(directoryLicenses(x).some(r=>r.status==='capacity-error'))x.checks.capacity=true;break;
case 'direct-license':if(!u||u.deleted){msg='Create/restore U3 first.';break;}u.directLicense=true;msg='Added independent direct license source; seat capacity still applies.';break;
case 'remove-direct-license':if(!u){msg='No U3.';break;}u.directLicense=false;msg='Direct assignment removed; group assignment may remain.';break;
case 'expand-seats':x.seats=3;msg='Fictional existing seat capacity set to 3; no purchase.';if(u&&directoryAccess(x,'U3','licensed-workload').allow)x.checks.license=true;break;
case 'invite':if(g){msg='U4 already exists.';break;}x.users.push({id:'U4',upn:'guest@partner.example',department:'External',enabled:true,deleted:false,guest:true,accepted:false,directLicense:false});msg='Created pending external representation; no redemption or grant.';break;
case 'guest-project':if(!g||g.deleted){msg='Invite U4 first.';break;}if(!x.groups.project.members.includes('U4'))x.groups.project.members.push('U4');msg='Project assignment recorded; redemption and account state still apply.';if(!directoryAccess(x,'U4','project-read').allow)x.checks.guestPending=true;break;
case 'redeem':if(!g||g.deleted){msg='Invite U4 first.';break;}g.accepted=true;msg='Modeled redemption completed.';if(directoryAccess(x,'U4','project-read').allow)x.checks.guestAccess=true;break;
case 'guest-disable':if(!g){msg='No U4.';break;}g.enabled=false;msg='Account disabled; modeled new request denied.';if(!directoryAccess(x,'U4','project-read').allow)x.checks.guestDisabled=true;break;
case 'guest-enable':if(!g){msg='No U4.';break;}g.enabled=true;msg='Account enabled; existing grants may become usable again.';break;
case 'guest-remove':x.groups.project.members=x.groups.project.members.filter(y=>y!=='U4');msg='Removed project entitlement independently of redemption.';if(g?.enabled&&g.accepted&&!directoryAccess(x,'U4','project-read').allow)x.checks.guestRevoked=true;break;
case 'delete':if(!u||u.deleted){msg='No live U3.';break;}u.deleted=true;u.enabled=false;x.roles=x.roles.filter(r=>r.id!=='U3');u.directLicense=false;x.checks.deleted=!directoryAccess(x,'U3','app-create').allow;msg='Modeled soft deletion; removed role/direct assignment. Real restore behavior varies by object and service.';break;
case 'restore':if(!u?.deleted){msg='No deleted U3.';break;}u.deleted=false;u.enabled=true;x.checks.restored=u.id==='U3';msg='Restored same fictional ID. Verify memberships and grants; role restoration is not assumed.';break;
default:return false;
}x.clock++;x.logs.push({sequence:x.clock,operation:a,result:msg});x.logs=x.logs.slice(-80);return true;}
function directoryPage(){let x=s.ms.directoryOps||directoryInit();return layout(B('course/chapter/users','← Users and groups')+'<h1>Directory operations workshop</h1>'+P('Original local model of directory records, effective app permissions, dynamic membership, limited license seats, guest redemption and soft deletion. No directory API is called. Real licensing allocation, deletion recovery, policy evaluation and provisioning behavior can differ.')+sec('Identity records',advTable(x.users.map(u=>({ID:u.id,UPN:u.upn,Department:u.department,Enabled:u.enabled,Deleted:u.deleted,Guest:u.guest,Redemption:u.accepted,Finance:directoryMembership(x,u.id).finance,Project:directoryMembership(x,u.id).project}))))+sec('Role and application records',advTable(x.roles)+advTable(x.apps))+sec('Modeled product allocation · capacity '+x.seats,advTable(directoryLicenses(x))+P('For teaching, seat allocation is deterministic in this model, not a promise of Microsoft licensing processing order.'))+sec('Perform operations',directoryOps.map(([a,t])=>'<button class="btn" data-action="directory-op" data-id="'+H(a)+'">'+H(t)+'</button>').join(''))+sec('Actual modeled access decisions',advTable(x.users.flatMap(u=>['app-create','project-read','licensed-workload'].map(op=>{let r=directoryAccess(x,u.id,op);return {ID:u.id,Operation:op,Allowed:r.allow,Reason:r.reason}}))))+sec('Independent verification sequence',P('Create U3, attempt denied creation, grant role, create app, remove role, retest denial. Move U3 to Finance and observe capacity error; set fictional existing capacity to 3. Invite U4, assign project before redemption, redeem, disable, enable, remove project. Soft-delete and restore U3; compare the same ID and current grants.')+P('Recorded outcomes: '+Object.keys(x.checks).filter(k=>x.checks[k]).join(', '))+advTable(x.logs.slice().reverse())+'<button class="btn" data-action="directory-reset">Reset fictional directory</button>'));}
function stepAndDirectoryAudit(){let checks=[],ck=(name,pass)=>checks.push({name,pass:!!pass});ck('29 source indexes / 1070 numbered source lines',sourceStepIndex.length===29&&sourceSteps.length===1070&&sourceStepMap.size===1070);ck('step source line and headings valid',sourceSteps.every(x=>x.line>0&&x.line<=sourceStepIndex[x.lab][1]&&x.heading>=-1&&x.heading<repoTraining.sc[x.lab][4].length));for(let i=0;i<29;i++){let html=stepPage(i);ck('lab '+i+' all step records rendered',(html.match(/class="un-source-step"/g)||[]).length===stepStats(i).total);}let x=directoryInit();for(const a of ['add','create-app','grant-role','create-app','remove-role','create-app','move','expand-seats','invite','guest-project','redeem','guest-disable','guest-enable','guest-remove','delete','restore'])directoryStep(x,a);ck('directory app permission lifecycle',x.checks.deniedBefore&&x.checks.allowed&&x.checks.revoked&&x.apps.length===1&&!directoryAccess(x,'U3','app-create').allow);ck('directory group and license capacity',x.checks.capacity&&x.checks.license&&directoryAccess(x,'U3','licensed-workload').allow);ck('directory guest lifecycle',x.checks.guestPending&&x.checks.guestAccess&&x.checks.guestDisabled&&x.checks.guestRevoked&&!directoryAccess(x,'U4','project-read').allow);ck('directory deletion/restore same object',x.checks.deleted&&x.checks.restored&&x.users.filter(u=>u.id==='U3').length===1);ck('directory workshop renders',directoryPage().includes('Directory operations workshop'));return checks;}


const qualificationPin='6d0a1812f8bf3cf41adf4687c2ba2031d1ee2cb8',qualificationPath='entra-training-unified/qualification-screen.json';
const qualificationUrl='https://raw.githubusercontent.com/infenergypower-bot/Five-Pillar/'+qualificationPin+'/'+qualificationPath;
const qualificationFlags=['Legacy names/APIs','Beta or preview','Potential cost/license','Potential write operation','Credential-related'];
const qualificationAdvice=['Check current supported Graph/Entra PowerShell and portal guidance; legacy wording may be historical.','Verify current API version, feature availability and prerequisites; preview is not automatically obsolete.','Confirm current license, existing capacity, cost and approval; do not activate a trial or paid service.','Verify role, scope, impact and rollback; do not execute source write commands blindly.','Do not export passwords, tokens, private keys or personal data; verify credential custody.'];
let qualData=null,qualError='',qualLoading=false,qualFilter={repo:'',flag:'',q:'',page:0};
function qualifyValid(d){return !!d&&d.asOf==='2026-11-27'&&Array.isArray(d.repos)&&d.repos.length===15&&Array.isArray(d.rows)&&d.rows.length===944&&d.rows.every(x=>Array.isArray(x)&&Number.isInteger(x[0])&&x[0]>=0&&x[0]<15&&typeof x[1]==='string'&&x[2]>=0&&Array.isArray(x[3])&&x[3].every(y=>Array.isArray(y)&&y[0]>=0&&y[0]<5&&Number.isInteger(y[1])&&Array.isArray(y[2]))&&!x[4])&&d.pins&&d.repos.every(n=>/^[a-f0-9]{40}$/.test(d.pins[n]||''));}
function qualRows(){return qualData?qualData.rows.filter(x=>(qualFilter.repo===''||String(x[0])===qualFilter.repo)&&(qualFilter.flag===''||(qualFilter.flag==='none'?x[3].length===0:x[3].some(y=>String(y[0])===qualFilter.flag)))&&(!qualFilter.q||(qualData.repos[x[0]]+'/'+x[1]).toLowerCase().includes(qualFilter.q.toLowerCase()))):[];}
function qualificationPage(){let d=qualData,rows=qualRows(),pages=Math.max(1,Math.ceil(rows.length/30));qualFilter.page=Math.max(0,Math.min(pages-1,qualFilter.page));let browse=d?'<form class="un-qualification-search"><label>Repository<select name="repo"><option value="">All repositories</option>'+d.repos.map((n,i)=>'<option value="'+i+'" '+(qualFilter.repo===String(i)?'selected':'')+'>'+H(n)+'</option>').join('')+'</select></label><label>Flag<select name="flag"><option value="">All flags</option>'+qualificationFlags.map((n,i)=>'<option value="'+i+'" '+(qualFilter.flag===String(i)?'selected':'')+'>'+H(n)+'</option>').join('')+'<option value="none" '+(qualFilter.flag==='none'?'selected':'')+'>No detected markers</option></select></label><label>Path contains<input name="q" value="'+H(qualFilter.q)+'"></label><button type="submit" class="btn primary">Filter</button></form>'+P(rows.length+' matching files · page '+(qualFilter.page+1)+' of '+pages)+rows.slice(qualFilter.page*30,(qualFilter.page+1)*30).map(x=>{let repo=d.repos[x[0]],url='https://github.com/'+repo+'/blob/'+d.pins[repo]+'/'+repoEncoded(x[1]);return detail(repo+' · '+x[1],P(x[2]+' characters · '+(x[3].length?'flags detected':'no matched patterns; not manually qualified'))+'<p>'+A(url,'Pinned file')+'</p>'+x[3].map(([n,count,lines])=>P(qualificationFlags[n]+' · '+count+' lines. '+qualificationAdvice[n])+'<p>'+lines.map(i=>A(url+'#L'+i,'Line '+i)).join(' · ')+'</p>').join(''));}).join('')+'<button class="btn" data-action="qual-page" data-value="-1" '+(qualFilter.page===0?'disabled':'')+'>Previous</button><button class="btn" data-action="qual-page" data-value="1" '+(qualFilter.page+1>=pages?'disabled':'')+'>Next</button>':'<button class="btn primary" data-action="qual-load" '+(qualLoading?'disabled':'')+'>Load pinned screening report</button>'+P(qualError||'No report downloaded until requested.');return layout(B('course/repositories','← Repository audit')+'<h1>Repository file qualification register</h1>'+P('944 pinned text/code assets screened across 15 repositories, including all 481 previously integrated documents. Pattern screening is not individual technical validation or license clearance.')+sec('Screening findings',advTable([{Files:944,Legacy:71,Preview:100,Cost:117,Modification:323,Credentials:303}])+P('Overlapping flags are not confirmed defects. All 15 pinned inventories are now enumerated (168,509 entries); 944 records were screened previously. Remaining relevance and technical qualification are unresolved. 93 official lab visuals have individual dispositions; many other binary assets are not reviewed.')+'<p>'+A('https://github.com/infenergypower-bot/Five-Pillar/blob/'+qualificationPin+'/'+qualificationPath,'Full pinned report')+'</p>')+sec('Qualification rules',qualificationFlags.map((n,i)=>detail(n,P(qualificationAdvice[i]))).join(''))+sec('Individual source files',browse));}
async function qualifyLoad(){if(qualLoading)return;qualLoading=true;qualError='';render();try{let r=await fetch(qualificationUrl,{credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw Error('HTTP '+r.status);let d=await r.json();if(!qualifyValid(d))throw Error('Unexpected report schema');qualData=d;}catch(e){qualError='Report load failed: '+String(e.message||e)+'. Use the pinned GitHub link.';}finally{qualLoading=false;if(current()==='course/qualification')render();}}
const tenantChecks=[["profile","Read signed-in identity","User.Read","/me?$select=id","user-get","Identify the tenant-local object and the signed-in identity; never share the ID."],["users","Sample directory users","User.ReadBasic.All","/users?$top=10&$select=id","user-list","Explain paging; a sample is not the full directory."],["memberships","Own direct memberships","User.Read","/me/memberOf?$top=10&$select=id","user-list-memberof","Distinguish direct and transitive membership and resource authorization."],["policies","Conditional Access policies","Policy.Read.All","/identity/conditionalAccess/policies?$top=10&$select=id,state","conditionalaccessroot-list-policies","Compare policy state and actual sign-in outcome; role/license may be required."],["signins","Sample sign-in events","AuditLog.Read.All","/auditLogs/signIns?$top=10&$select=id,status","signin-list","Interpret sign-in result and policy details in approved tenant; role/license may be required."],["applications","Sample app registrations","Application.Read.All","/applications?$top=10&$select=id,appId","application-list","Distinguish app ID, object ID and service principal."],["roles","Directory role assignments","RoleManagement.Read.Directory","/roleManagement/directory/roleAssignments?$top=10&$select=id,roleDefinitionId,directoryScopeId","rbacapplication-list-roleassignments","Inspect active scope versus eligible privilege."],["packages","Access packages","EntitlementManagement.Read.All","/identityGovernance/entitlementManagement/accessPackages?$top=10&$select=id","entitlementmanagement-list-accesspackages","Package definition does not prove assignment delivery; feature/role may be required."]],tenantScript="# Identity Academy — read-only evidence collector. No login, consent, resource creation or writes to Microsoft Graph.\n# Run in a dedicated PowerShell process with an existing authorized delegated Microsoft Graph context.\n# Inspect this script before use. Only run a selected exercise using already approved read-only scopes.\nparam(\n [Parameter(Mandatory=$true)][ValidateSet('profile','users','memberships','policies','signins','applications','roles','packages')][string]$Exercise,\n [Parameter(Mandatory=$true)][ValidatePattern('^[A-Z0-9-]{8,80}$')][string]$Challenge,\n [Parameter(Mandatory=$true)][guid]$ExpectedTenantId\n)\n$ErrorActionPreference = 'Stop'\n$spec = @{\n 'profile' = @{ Scope = 'User.Read'; Path = '/me?$select=id' }\n 'users' = @{ Scope = 'User.ReadBasic.All'; Path = '/users?$top=10&$select=id' }\n 'memberships' = @{ Scope = 'User.Read'; Path = '/me/memberOf?$top=10&$select=id' }\n 'policies' = @{ Scope = 'Policy.Read.All'; Path = '/identity/conditionalAccess/policies?$top=10&$select=id,state' }\n 'signins' = @{ Scope = 'AuditLog.Read.All'; Path = '/auditLogs/signIns?$top=10&$select=id,status' }\n 'applications' = @{ Scope = 'Application.Read.All'; Path = '/applications?$top=10&$select=id,appId' }\n 'roles' = @{ Scope = 'RoleManagement.Read.Directory'; Path = '/roleManagement/directory/roleAssignments?$top=10&$select=id,roleDefinitionId,directoryScopeId' }\n 'packages' = @{ Scope = 'EntitlementManagement.Read.All'; Path = '/identityGovernance/entitlementManagement/accessPackages?$top=10&$select=id' }\n}\n$context = Get-MgContext\nif (-not $context -or $context.AuthType -ne 'Delegated') { throw 'An existing authorized delegated Graph PowerShell session is required. This script does not sign in.' }\nif ($context.TenantId -ne $ExpectedTenantId.ToString()) { throw 'Wrong tenant; stop and verify the intended authorized training tenant.' }\nif ($context.Environment -ne 'Global') { throw 'Only global Microsoft Graph is supported by this training collector.' }\n$task = $spec[$Exercise]\nif ($context.Scopes -notcontains $task.Scope) { throw 'Required exact read-only scope is absent. Do not grant new consent merely for this exercise.' }\n# Refuse any scope outside this deliberately narrow allowlist, including write/manage scopes.\n$approvedScopes = @('User.Read','User.ReadBasic.All','Policy.Read.All','AuditLog.Read.All','Application.Read.All','RoleManagement.Read.Directory','EntitlementManagement.Read.All','openid','profile','email','offline_access')\nif (@($context.Scopes | Where-Object { $_ -notin $approvedScopes }).Count -gt 0) { throw 'Use a separate approved read-only session; an unapproved scope is present.' }\n$record = [ordered]@{ schema='identity-academy-tenant-read-v1'; exercise=$Exercise; challenge=$Challenge; observedAt=[DateTime]::UtcNow.ToString('o'); outcome='read-error'; sampleCount=0; morePages=$false; method='GET'; apiVersion='v1.0'; scope=$task.Scope }\ntry {\n $response=Invoke-MgGraphRequest -Method GET -Uri ('https://graph.microsoft.com/v1.0'+$task.Path) -OutputType Hashtable\n if ($Exercise -eq 'profile') { if (-not $response['id']) { throw 'Profile response has no ID.' }; $record.sampleCount=1 }\n else { if (-not $response.ContainsKey('value')) { throw 'Unexpected collection response.' }; $record.sampleCount=@($response['value'] | Where-Object { $_ -ne $null }).Count; if ($record.sampleCount -gt 10) { throw 'Unexpected sample size.' }; $record.morePages=[bool]$response['@odata.nextLink'] }\n $record.outcome='read-ok'\n} catch {\n # Never export raw errors, request bodies, identifiers, tokens or account information.\n $record.outcome='read-error'; $record.sampleCount=0; $record.morePages=$false\n}\n$record | ConvertTo-Json -Depth 3\n";
s.ms.tenantEvidence=s.ms.tenantEvidence||{runs:{},portfolio:{},challenge:''};
const tenantE=s.ms.tenantEvidence;
function tenantChallenge(){if(!tenantE.challenge){let a=new Uint32Array(3);if(typeof crypto!=='undefined'&&crypto.getRandomValues)crypto.getRandomValues(a);else{a[0]=Date.now()>>>0;a[1]=Math.floor(Math.random()*0xffffffff);a[2]=Math.floor(Math.random()*0xffffffff);}tenantE.challenge='LAB-'+Array.from(a,x=>x.toString(16).toUpperCase().padStart(8,'0')).join('-');persist();}return tenantE.challenge;}
function validateTenantRead(raw,challenge){try{if(typeof raw!=='string'||raw.length>5000)throw Error('Enter only sanitized JSON.');let x=JSON.parse(raw),ks=['schema','exercise','challenge','observedAt','outcome','sampleCount','morePages','method','apiVersion','scope'];if(!plainRecord(x)||Object.keys(x).length!==ks.length||!ks.every(k=>Object.prototype.hasOwnProperty.call(x,k)))throw Error('Unexpected fields. Do not import raw Graph data or identifiers.');let t=tenantChecks.find(y=>y[0]===x.exercise);if(x.schema!=='identity-academy-tenant-read-v1'||!t||x.challenge!==challenge||x.scope!==t[2]||x.method!=='GET'||x.apiVersion!=='v1.0'||!['read-ok','read-error'].includes(x.outcome)||!Number.isInteger(x.sampleCount)||x.sampleCount<0||x.sampleCount>10||typeof x.morePages!=='boolean'||typeof x.observedAt!=='string'||!Number.isFinite(Date.parse(x.observedAt))||Date.parse(x.observedAt)>Date.now()+300000||Date.parse(x.observedAt)<Date.now()-86400000)throw Error('Record does not match challenge, exercise or 24-hour time window.');if(x.outcome==='read-error'&&(x.sampleCount!==0||x.morePages))throw Error('Error record must not claim results.');if(x.exercise==='profile'&&(x.sampleCount>1||x.morePages||x.outcome==='read-ok'&&x.sampleCount!==1))throw Error('Invalid profile result.');return {ok:true,record:x};}catch(e){return {ok:false,error:String(e.message||e)};}}
let tenantMessage='';
const portfolioStatus=['not-attempted','blocked','self-reported-performed','assessor-reviewed-self-reported'];
function portfolioRecord(id){return tenantE.portfolio[id]||{status:'not-attempted',baseline:'',positive:'',negative:'',rollback:'',explanation:'',reviewer:''};}
function tenantStats(){return {read:tenantChecks.filter(x=>tenantE.runs[x[0]]?.outcome==='read-ok').length,reported:depthRows.filter(r=>portfolioRecord(r.id).status==='self-reported-performed').length,reviewed:depthRows.filter(r=>portfolioRecord(r.id).status==='assessor-reviewed-self-reported').length,blocked:depthRows.filter(r=>portfolioRecord(r.id).status==='blocked').length};}
function tenantPage(){let st=tenantStats(),challenge=tenantChallenge();return layout(B('course/practice','← Practice')+'<h1>Authorized real-tenant competency pathway</h1>'+P('No tenant is connected. This academy does not sign in, request consent, create resources or run Graph. Work only in an isolated or explicitly approved training tenant with existing licenses and permissions. Evidence is self-reported, not independently attested.')+sec('1 · Real read-only exercises',P('Use an existing authorized delegated Microsoft.Graph.Authentication PowerShell session in a dedicated process. Verify the expected tenant GUID locally. The collector accepts only a narrow approved read-only scope allowlist and performs one selected GET. Do not grant new consent or activate a paid service merely to pass. Record blockers if access is unavailable.')+P('Current challenge: '+challenge)+'<button class="btn" data-action="tenant-new-challenge">New challenge</button><button class="btn primary" data-action="tenant-download">Download read-only PowerShell collector</button>'+P('Inspect the script first. Example: .\\tenant-read-evidence.ps1 -Exercise profile -Challenge '+challenge+' -ExpectedTenantId <authorized-test-tenant-guid>. Keep tenant IDs outside the academy.')+tenantChecks.map(x=>detail(x[1]+' · '+x[0],P('Existing approved scope: '+x[2])+P('GET '+x[3])+P(x[5])+'<p>'+A('https://learn.microsoft.com/graph/api/'+x[4]+'?view=graph-rest-1.0','Microsoft documentation')+'</p>'+P(tenantE.runs[x[0]]?'Imported self-reported '+tenantE.runs[x[0]].outcome+' · '+tenantE.runs[x[0]].sampleCount+' sample records':'No imported result'))).join('')+'<form class="un-tenant-import"><label>Paste sanitized collector JSON<textarea name="record"></textarea></label><button class="btn primary" type="submit">Validate and save report</button></form>'+P(tenantMessage||'A structurally valid report is not cryptographic evidence; a read does not prove configuration competency.')+P(st.read+'/8 successful imported read reports. No live tenant calls made by this academy.'))+sec('2 · Objective-level competency portfolio',P('For each objective, document approved baseline, performed operation, positive and negative outcomes, cleanup, mechanism and an optional qualified assessor review. Do not store names, IDs, secrets, screenshots or confidential logs. Review status is self-reported.')+P(st.reported+' performed self-reported · '+st.reviewed+' assessor-reviewed self-reported · '+st.blocked+' blocked.')+msDomains.map((d,i)=>B('course/tenant-domain/'+i,d[0]+' · '+d[2].length+' objectives')).join('')));}
function tenantDomainPage(n){if(![0,1,2,3].includes(n))n=0;let rows=depthRows.filter(r=>r.id.startsWith('D'+(n+1)+'.'));return layout(B('course/tenant','← Real-tenant pathway')+'<h1>'+H(msDomains[n][0])+' · competency records</h1>'+P('Use approved scope, existing entitlement, necessary role, change authorization and rollback. A simulation, read report or self-report is not independent real-tenant competency evidence.')+rows.map(r=>{let a=portfolioRecord(r.id),l=gapMap.get(r.id);return detail(r.id+' · '+r.title,P('Scenario: '+l[2])+P('Configuration: '+r.configuration)+P('Verification: '+r.verification)+P('Fault/recovery reference: '+l[3].find(f=>f[0]===l[5])[1])+B(gapRoute(r.id),'Practice locally first')+(r.lab!==null&&r.lab!==undefined?B('course/lab-steps/'+r.lab,'Review upstream lab steps'):'')+'<p>'+A(msGuide,'Current study guide')+'</p><form class="un-tenant-portfolio" data-id="'+H(r.id)+'"><label>Evidence status<select name="status">'+portfolioStatus.map(k=>'<option value="'+k+'" '+(a.status===k?'selected':'')+'>'+H(k.replace(/-/g,' '))+'</option>').join('')+'</select></label>'+[['baseline','Approval, isolated scope and baseline (or blocker)'],['positive','Approved operation and observed positive result'],['negative','Observed denial or failure boundary'],['rollback','Cleanup or restored state and verification'],['explanation','Explain mechanism and why evidence proves outcome'],['reviewer','Non-identifying assessor review reference (self-reported)']].map(([k,label])=>'<label>'+H(label)+'<textarea name="'+k+'">'+H(a[k])+'</textarea></label>').join('')+'<button class="btn" type="submit">Save portfolio record</button></form>');}).join(''));}
function validatePortfolio(a){if(!plainRecord(a)||!portfolioStatus.includes(a.status)||!['baseline','positive','negative','rollback','explanation','reviewer'].every(k=>typeof a[k]==='string'&&a[k].length<=4000))return false;if(a.status==='blocked')return a.baseline.trim().length>=10;if(['self-reported-performed','assessor-reviewed-self-reported'].includes(a.status)){if(!['baseline','positive','negative','rollback','explanation'].every(k=>a[k].trim().length>=10))return false;if(a.status==='assessor-reviewed-self-reported'&&a.reviewer.trim().length<10)return false;}return true;}
function qualificationTenantAudit(){let out=[],ck=(name,pass)=>out.push({name,pass:!!pass});ck('qualification route',qualificationPage().includes('944 pinned'));ck('fixed read-only tasks',tenantChecks.length===8&&tenantChecks.every(x=>x[3].startsWith('/')&&x[2].includes('Read')&&!x[2].includes('Write'))&&tenantScript.includes('Invoke-MgGraphRequest -Method GET')&&!tenantScript.includes('Connect-MgGraph'));let x={schema:'identity-academy-tenant-read-v1',exercise:'profile',challenge:'LAB-TEST-123',observedAt:new Date().toISOString(),outcome:'read-ok',sampleCount:1,morePages:false,method:'GET',apiVersion:'v1.0',scope:'User.Read'};ck('valid sanitized report',validateTenantRead(JSON.stringify(x),x.challenge).ok);ck('raw ID rejected',!validateTenantRead(JSON.stringify({...x,tenantId:'not allowed'}),x.challenge).ok);ck('wrong challenge rejected',!validateTenantRead(JSON.stringify(x),'different').ok);ck('write rejected',!validateTenantRead(JSON.stringify({...x,method:'POST'}),x.challenge).ok);ck('incomplete portfolio rejected',!validatePortfolio({...portfolioRecord('D1.1'),status:'self-reported-performed'}));for(let n=0;n<4;n++)ck('tenant portfolio domain '+n+' forms',(tenantDomainPage(n).match(/class="un-tenant-portfolio"/g)||[]).length===msDomains[n][2].length);return out;}


const labQualification=[["external-prerequisite","Do not activate trials or subscriptions merely to follow this lab. Identify existing tenant, role and assigned entitlement separately.","Verify authorized test scope and existing licensing; no billing change.","https://learn.microsoft.com/en-us/entra/fundamentals/licensing"],["adapted","Use modern Graph PowerShell instead of legacy AzureAD/MSOnline instructions. Role removal must be followed by effective-access testing.","Record object ID locally, role scope, actual create/deny outcome and restored test state.","https://learn.microsoft.com/powershell/microsoftgraph/migration-steps"],["adapted","Separate DNS ownership proof, display metadata, immutable tenant ID and privacy/contact configuration; do not modify production domain or billing identity.","Verify approved metadata and TXT challenge without changing existing MX.",""],["updated","Group-based license assignment is managed in the Microsoft 365 admin center; inspect processing errors and direct/other inherited sources.","Check existing capacity, usage location, evaluated membership, assignment source and enabled plan.","https://learn.microsoft.com/entra/identity/users/licensing-groups-assign"],["adapted","Distinguish external self-service sign-up from B2B invitation and resource access. Review current External ID flow support before configuration.","Test authorized invitation and denied unrelated resource access; do not relax tenant-wide policy.",""],["adapted","Use current supported Graph invitation operation and CSV template; invitation and redemption are different.","Verify per-row outcomes, guest redemption and actual target access.","https://learn.microsoft.com/powershell/microsoftgraph/migration-steps"],["external-prerequisite","External Google provider setup requires authorized provider resources and current consent/redirect configuration. Do not create or disclose secrets.","Check approved issuer/redirect, guest redemption and resource entitlement; no provider account creation.",""],["external-prerequisite","AD DS/Connect requires isolated supported server/client infrastructure and current setup prerequisites. Do not execute VM deployment or domain-wide recovery commands.","Verify source/import/export/target and separate hybrid join evidence; preserve source authority and cleanup.",""],["updated","Authentication Methods policy manages eligible methods; legacy per-user enforcement is separate. Legacy method management retired September 30, 2025.","Inspect registered method, authentication details and applicable CA outcome.","https://learn.microsoft.com/en-us/entra/identity/authentication/concept-authentication-methods-manage"],["updated","Use unified Authentication Methods policy and separate SSPR scope/verification settings. Do not use legacy method management.","Verify included/excluded user and supported hybrid writeback outcome where applicable.","https://learn.microsoft.com/en-us/entra/identity/authentication/how-to-authentication-methods-manage"],["external-prerequisite","Windows/Linux Azure VM login requires supported existing VM, extension, network and login role. Resource management rights do not establish guest login.","Test ordinary/admin login boundaries only in an approved existing VM; no deployment.",""],["license-gated","Resource PIM requires current applicable entitlement and resource scope; eligible assignment is not active access.","Verify approved active interval, actual action, expiry and alternate role paths.","https://learn.microsoft.com/en-us/entra/id-governance/privileged-identity-management/pim-getting-started"],["adapted","Smart lockout and banned-password protection are distinct. Do not generate repeated real failed logins.","Use modeled threshold evidence and approved recovery design.",""],["updated","Use scoped report-only pilot, independent emergency path and real representative sign-in evidence before approved enforcement.","Verify matching policy controls, intended block, unaffected test user and recovery.","https://learn.microsoft.com/en-us/entra/identity/conditional-access/plan-conditional-access"],["updated","Microsoft scheduled legacy Identity Protection risk policies for retirement October 1, 2026. Use current risk-based Conditional Access guidance, not legacy policy toggles.","Distinguish user and sign-in risk; verify actual policy event and approved remediation.","https://learn.microsoft.com/entra/id-protection/howto-identity-protection-configure-risk-policies"],["updated","Use the current registration campaign for supported passkey or Authenticator registration; do not treat historical Identity Protection registration instructions as current.","Verify eligible registration prompt and separate policy enforcement.","https://learn.microsoft.com/entra/identity/authentication/how-to-mfa-registration-campaign"],["external-prerequisite","Vault and VM creation may incur cost. Managed identity, token audience and vault data permissions are separate.","Use existing authorized resources only; verify narrow read and denied write without exporting secret values.",""],["license-gated","Cloud Discovery visibility, sanction classification and supported enforcement are distinct. Confirm current feature entitlement/integration.","Verify actual traffic and supported restriction; a tag alone does not prove block.","https://learn.microsoft.com/en-us/entra/fundamentals/licensing"],["license-gated","Session routing, monitoring and blocking require supported app/client and configured integration; do not enable paid services.","Verify actual routed session, event and action-level outcome.","https://learn.microsoft.com/en-us/entra/fundamentals/licensing"],["adapted","Use supported OAuth/OIDC flow and current Graph identity platform concepts. Never embed confidential secret in public browser code.","Verify client ID, exact redirect, scope/role and resource-level denial.","https://learn.microsoft.com/en-us/graph/permissions-overview"],["adapted","Enterprise application is tenant-local service principal; assignment and resource authorization differ.","Test assigned versus unassigned sign-in and actual resource operation.","https://learn.microsoft.com/en-us/graph/permissions-overview"],["adapted","Requested permission and actual consent grant differ. Broad admin consent is a high-impact change, not an exercise prerequisite.","Inspect grant and scoped authorized revocation; verify unrelated action denied.","https://learn.microsoft.com/en-us/graph/permissions-reference"],["license-gated","Catalog roles, package resource roles and actual assignments are separate. Confirm current governance entitlement.","Check dependent packages before authorized cleanup; no real deletion.","https://learn.microsoft.com/en-us/entra/id-governance/identity-governance-overview"],["license-gated","Terms of use is an applicable acceptance condition, not entitlement. Use approved policy text and version.","Verify acceptance/refusal and version history; do not publish real legal policy.","https://learn.microsoft.com/en-us/entra/fundamentals/licensing"],["license-gated","External lifecycle after last package assignment is not universal guest removal; review alternate grants and retention.","Verify actual assignment loss, account state and allowed/denied resource behavior.","https://learn.microsoft.com/en-us/entra/id-governance/identity-governance-overview"],["license-gated","Review definition, instance, decision and applied result differ; check current review scope/entitlement.","Verify decision application and alternate grants, not just completion label.","https://learn.microsoft.com/en-us/entra/id-governance/manage-access-review"],["license-gated","Directory PIM supports time-limited activation and approval under applicable entitlement. Preserve independent emergency access.","Verify eligible-only denial, active scoped operation, expiry and alternate authority.","https://learn.microsoft.com/en-us/entra/id-governance/privileged-identity-management/pim-getting-started"],["external-prerequisite","Sentinel workspace/log routing can incur ingestion and retention costs. Use existing authorized data or local fixtures.","Validate actual query schema, time range, source and count; no workspace creation.",""],["adapted","Secure Score indicates recommended posture improvements, not proof of an effective security control.","Verify actual intended operation and denied unrelated action; no paid activation to increase score.",""]];
const qualificationStatusLabels={'updated':'Current guidance checked · adaptation','adapted':'Conceptual adaptation · verify live procedure','license-gated':'Entitlement-gated · verify exact feature','external-prerequisite':'External infrastructure or account prerequisite'};
function labQualificationCard(n){const a=labQualification[n];return detail('Qualification decision · '+qualificationStatusLabels[a[0]],P(a[1])+P('Acceptance evidence: '+a[2])+(a[3]?'<p>'+A(a[3],'Current Microsoft reference reviewed')+'</p>':P('Exact current live procedure and prerequisites still require verification before execution.'))+P('Reviewed at topic/operation level against existing pinned walkthrough, not a line-by-line manual approval of every upstream step. No live execution performed.'));}
function labQualificationPage(){return layout(B('course/qualification','← Source register')+'<h1>Official SC-300 lab qualification decisions</h1>'+P('29 pinned labs; source-specific decisions about updated guidance, prerequisite constraints and evidence. A decision record does not certify every upstream instruction as current or safe.')+repoTraining.labs.map((l,n)=>sec('Lab '+String(n).padStart(2,'0')+' · '+l[1],phase1LabForNumber(n)+labQualificationCard(n)+repoSourceButton(repoSourceMap.get('sc-'+n),'Read pinned source')+B('course/lab-steps/'+n,'Open exact numbered instructions'))).join(''));}
const glossaryCoverageTexts=()=>[...Object.values(teachingUnits).flat().map(x=>[x[0],...x.slice(6)].join(' ')),...depthRows.map(r=>[r.title,r.mechanism,r.configuration,r.verification].join(' ')),...granularLessons.map(r=>[r[4],r[5],r[6],r[7],r[8]].join(' '))];
const coverageAcronyms=['ID','API','DNS','MFA','SSO','RBAC','URI','URL','SPA','AD','CIEM','WAF','SAN','PAW','AI','FIDO','AAAA','SSPR','TAP','PKCE','JWT','OIDC','SAML','SCIM','PHS','PTA','PRT','CAE','PIM','GSA','KQL','MSAL','CBA','SDK','RTO','RPO','DLP','SID','SPN','TGT','LDAP','GPO','FSMO','MDM','DHCP','TLS','HTTP','TCP','JSON','CSV','VM','IP','ICMP','SMB','DFSR'];
function vocabCoverage(){let known=new Set(atomicTerms.flatMap(x=>[x[0],...x[5]]).map(x=>x.toUpperCase())),texts=glossaryCoverageTexts(),joined=texts.join(' '),found=coverageAcronyms.filter(k=>new RegExp('\\\\b'+k+'\\\\b','i').test(joined));return {texts:texts.length,checked:coverageAcronyms.length,found:found.length,missing:coverageAcronyms.filter(k=>!known.has(k))};}
function planPage(){let v=vocabCoverage(),t=tenantStats(),q=qualData?qualData.rows.length:944;return layout(B('course/home','← Course home')+'<h1>Academy execution and completion register</h1>'+P('Acceptance criteria distinguish a completed software feature from qualified source content and actual learner competency. No paid subscription, trial or resource is required by this release.')+sec('1 · Source qualification',P('Phase 1 in progress. 944 previously screened assets, 29 lab topic decisions, 481 previously integrated records, plus 39 newly retrieved sources with four new chapter adaptations. Acceptance for full repository qualification: enumerate all upstream files at a fixed commit, classify relevance, manually validate every in-scope technical instruction against supported current guidance, and resolve or explicitly exclude every item. Not met: full inventories are now enumerated; remaining in-scope relevance and operation-level qualification are unresolved. Automated screening is not semantic review.')+B('course/qualification','File screening register')+B('course/lab-qualification','29 lab decisions')+'<p>'+A('https://github.com/infenergypower-bot/Five-Pillar/blob/training-entra-v6-exam-20261126/entra-training-unified/MASTER-PHASE-TRACKER.md','Master ten-phase tracker and execution log')+'</p>')+phase1GateSection()+sec('2 · Vocabulary',P(atomicTerms.length+' glossary definitions. '+v.texts+' primary teaching texts scanned; '+v.checked+' explicit core acronym checks; '+v.missing.length+' unresolved aliases in this check.')+P('Acceptance for this scoped check: every named core acronym maps to an explanation. Broader exhaustive vocabulary across every source, screenshot, technical field and practice path remains unverified.')+B('course/glossary','Technical glossary'))+sec('3 · Tenant competency',P('Completed software: eight constrained read-only exercises, 98 portfolio records, sanitized evidence import, scope allowlist and ten mocked PowerShell execution tests. No tenant connected or live calls made. Imported read successes: '+t.read+'/8. Self-reported performed '+t.reported+'; self-reported reviewed '+t.reviewed+'; blocked '+t.blocked+'.')+P('Acceptance for actual competency: learner executes approved tasks in an isolated tenant with available entitlement, documents baseline, positive/negative tests, recovery, explanation and qualified assessor review. Not met without authorization and learner performance. Do not fabricate results or enable paid resources.')+B('course/tenant','Real tenant competency pathway'))+sec('4 · Verification and release',P('Run automated suite; exercise qualification, glossary and portfolio in an isolated browser; test PowerShell with mocked responses; preserve existing progress and backup compatibility. See live results.')+'<p>'+A('/qa-unified','Live automated verification')+'</p>'+B('course/backup','Backup and restore')));}
function planAudit(){let v=vocabCoverage();return [{name:'29 source-specific lab decisions',pass:labQualification.length===29&&labQualification.every(x=>qualificationStatusLabels[x[0]]&&x[1].length>30&&x[2].length>30)&&labQualificationPage().includes('29 pinned labs')},{name:'primary lesson vocabulary coverage',pass:v.texts===165&&v.missing.length===0},{name:'completion register explicit blockers',pass:planPage().includes('Not met')&&planPage().includes('No tenant connected')},{name:'read-only collector strict allowlist and malformed response guard',pass:tenantScript.includes('$approvedScopes')&&tenantScript.includes('Unexpected collection response')&&tenantScript.includes('Unexpected sample size')}];}


