function phase1EvidenceFor(n){let e=phase1Sc300Evidence,v=e.visual.filter(x=>x[0]===n),c=e.code.filter(x=>x[0]===n),m=e.missing.filter(x=>x[0]===n);return detail('Source evidence and exclusions · '+v.length+' visuals / '+c.length+' code blocks / '+m.length+' missing references',P('Visuals were reviewed at contact-sheet resolution; archival images are not current procedural authority. Code decisions do not authorize execution.')+v.map(x=>detail(x[1].split('/').pop()+' · '+x[3],P(x[2])+P(x[4]))).join('')+c.map(x=>detail('Lines '+x[1]+'–'+x[2]+' · '+x[4],P(x[3])+P(x[5]))).join('')+m.map(x=>detail(x[1]+' · '+x[3],P(x[2]))).join('')+P('Exact source-linked evidence is retained in the repository.'));}
function phase1LabDetail(r){return detail(r.title,'<h3>Source decision</h3>'+P(r.reason)+'<h3>Prerequisites and cost boundaries</h3>'+P(r.prereq)+'<h3>How the operation works</h3>'+P(r.mechanism)+'<h3>Independent practice</h3>'+P(r.practice)+detail('Reveal answer and verification',P(r.answer))+'<h3>Source and current guidance</h3><p>'+A('https://github.com/'+phase1LabBatch.repository+'/blob/'+phase1LabBatch.pin+'/'+repoEncoded(r.path),r.path)+'</p>'+r.refs.map(u=>'<p>'+A(u,u)+'</p>').join('')+P('Source body retrieved and topic adapted. Available screenshots and fenced code blocks have individual dispositions; full operation-level validation and real tenant execution remain unverified.')+phase1EvidenceFor(r.number));}
function phase1LabLesson(c){const rows=phase1LabBatch.rows.filter(r=>r.chapter===c[0]);return rows.length?sec('Phase 1 · official lab qualification and safer practice',rows.map(phase1LabDetail).join('')):'';}
